window.BENAK_QUOTES = [{"slug":"kalendar","title_hr":"Kalendar","title_en":"The Calendar","hr":["I godina nova dođe,","djedu, baki pišeš pismo.","Sve nam tako lijepo prođe –","za godinu stariji smo!"],"en":["Then the New Year comes around,","you write \"Grandpa, Granny dear…\";","all goes by so safe and sound,","we are older by a year!"],"day":"01-01","occ_hr":"Nova godina","occ_en":"New Year's Day"},{"slug":"vrati-mi-poljupce","title_hr":"Vrati mi poljupce","title_en":"Give Me Back My Kisses","hr":["Za tople poglede","ljubit sam te znao.","Za svaki tvoj poljubac,","po dva sam ti dao."],"en":["For your warm glances","I would kiss you anew.","For every single kiss,","I gave two back to you."],"day":"01-02","occ_hr":"napisano na današnji dan, 1985.","occ_en":"written on this day in 1985"},{"slug":"postovana-gospodo-ana","title_hr":"Poštovana gospođo Ana!","title_en":"Dear Madam Ana!","hr":["Pratili Vas samo sretni dani,","nek' Vam bude bolje nego lani.","Među sobom divno se družili,","svoje snove sretno ostvarili."],"en":["May only happy days be yours to know,","and fare much better than a year ago.","May you have lovely times when you all meet,","and see your dreams come true, your joy complete."],"day":"01-03"},{"slug":"zima","title_hr":"Zima","title_en":"Winter","hr":["Sva se djeca","zdrava, čila,","kraj ognjišta sakupila","i miluju macu slatku,","koja prede sve po taktu."],"en":["All the children,","hale and bright,","round the hearth have gathered tight,","stroking Kitty, soft and sweet,","who purrs on and keeps the beat."],"day":"01-04"},{"slug":"draga-generacijo-2013","title_hr":"Draga generacijo!","title_en":"My Dear Generation!","hr":["Svi u zdravlju sreću uživali","Godinicu u ljepoti snili","Vedri dani veseli bez rada","Ne tražite Svetog Petra vrata."],"en":["May you all enjoy good health and cheer,","dream in beauty all the coming year,","bright and merry days, and work can wait:","don't go looking for Saint Peter's gate."],"day":"01-05"},{"slug":"sveta-tri-kralja","title_hr":"Sveta tri kralja","title_en":"The Three Kings","hr":["Čuo jesam da se kralj rodio.","Iz daljine ja sam dohodio.","Došao sam da mu se poklonim","i bogate darove donosim."],"en":["Word has reached me of a king's new birth;","I have come from far across the earth.","I have come to bow before him low,","bringing costly gifts I shall bestow."],"day":"01-06","occ_hr":"Sveta tri kralja","occ_en":"Epiphany"},{"slug":"da-se-ne-zaboravi","title_hr":"Da se ne zaboravi","title_en":"Lest It Be Forgotten","hr":["Još se sjećam svojega djetinjstva","i mladosti što je Sopjem prošla.","Svu ljepotu srcem dajem Sopju,","u vremenu kad je starost došla."],"en":["I remember still my childhood days","and my youth, in Sopje lived and passed;","with my heart I give all beauty to Sopje,","now that old age comes to me at last."],"day":"01-07","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"nedjelja-je-i-veselje-traje","title_hr":"Nedjelja je i veselje traje","title_en":"It's Sunday, and the Merriment Goes On","hr":["Šokadijo mili zavičaju,","najljepša si u zemaljskom raju.","Svako selo ima tamburaša,","lijepih cura i čarobnih snaša!"],"en":["Šokadija, my dear homeland, my own,","in earthly paradise the fairest known!","Each village has its tamburica band,","fair girls and charming wives on every hand!"],"day":"01-08","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"zimska-idila","title_hr":"Zimska idila","title_en":"Winter Idyll","hr":["Sniježak prši, a vatra pucketa,","topla soba kao usred ljeta.","Kamin grije, žena kavu sprema,","mačor prede, kraj kamina drijema."],"en":["The snowflakes swirl, the fire crackles bright,","the room's as warm as summer at its height.","The fireplace warms, the wife makes coffee, and","the tomcat purrs and dozes close at hand."],"day":"01-09"},{"slug":"najveca-neznalica","title_hr":"Najveća neznalica","title_en":"The Greatest Know-Nothing","hr":["Tko najmanje na tom svijetu znade,","to je šofer kada zbraja jade.","Dok umoran u kabini drijema,","šofer ne zna što se njemu sprema."],"en":["Who in this world knows least of anyone?","The driver, counting troubles one by one.","While dozing in his cab, worn out and sore,","the driver doesn't know what lies in store."],"day":"01-10","occ_hr":"napisano na današnji dan, 1988.","occ_en":"written on this day in 1988"},{"slug":"u-mom-narucju","title_hr":"U mom naručju","title_en":"In My Arms","hr":["U naručju kad si mome,","ja ni za šta ne znam više.","Da l' mećava snježna vije,","il' jesenje liju kiše."],"en":["When you're in my arms, my dearest,","all I know is us together,","be it snowy blizzards blowing","or the rains of autumn weather."],"day":"01-11"},{"slug":"kalendar","title_hr":"Kalendar","title_en":"The Calendar","hr":["U siječnju se drva sijeku","i djed djeci priča bajke,","u veljači snijeg još vije,","ulicama jure sanjke."],"en":["In January wood is chopped,","Grandpa's tales the children hear;","February, snow still swirling,","sledges whizzing far and near."],"day":"01-12"},{"slug":"dodi-voljena","title_hr":"Dođi voljena","title_en":"Come, My Beloved","hr":["I tugu je lakše","nositi udvoje,","kad ju se s nekim","iskreno dijeli."],"en":["Sorrow, too, is lighter","when carried by two,","if someone shares it","with a heart sincere."],"day":"01-13"},{"slug":"slavonac-u-brdima","title_hr":"Slavonac u brdima!","title_en":"A Slavonian in the Hills!","hr":["Svud je lijepo za trenutak.","Da me pusta želja mine,","ja poželih topli kutak,","bijela kruha i slanine."],"en":["Each place pleases at first look;","so this longing would be through,","all I wished was a warm nook,","some white bread, and bacon too."],"day":"01-14"},{"slug":"rodena-gruda","title_hr":"Rođena gruda","title_en":"Native Soil","hr":["Ako ti se prohtje, u bijeli svijet pođi.","Život bolne drame priređuje često.","A kada se vratiš, na grudi mi dođi.","Tu ćeš naći uvijek svoje toplo gnijezdo."],"en":["If you should wish it, go into the wide world, go!","For life will often stage its dramas full of pain.","But when you come back home, come to my breast, and so","you'll always find your own warm nest right here again."],"day":"01-15","occ_hr":"napisano na današnji dan, 1976.","occ_en":"written on this day in 1976"},{"slug":"spoj-na-kraju-ulice","title_hr":"Spoj na kraju ulice","title_en":"A Date at the End of the Street","hr":["Čekam, a studen me bije.","Magla se spušta plava.","Na nebu zvijezde se pale","i grad polako već spava."],"en":["I am waiting; cold bites hard.","Blue, the mist comes settling down.","In the sky the stars are kindling,","slowly, sleep has claimed the town."],"day":"01-16"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["Prši sniježak u noćima hladnim,","žena grije od furune bolje.","Ljubljah strasno u noćima dugim,","došla djeca, i bez moje volje."],"en":["On chilly nights the snow would flurry down;","a wife beats any stove against the chill.","I loved with passion through the long, long nights:","the children came, and that without my will."],"day":"01-17"},{"slug":"ja-mrzim","title_hr":"Ja mrzim!","title_en":"I Hate!","hr":["Ja mrzim dvorce","i ne volim kule,","tvrđave i vile","i sva zdanja","bez ljudske topline."],"en":["I hate castles","and do not love towers,","fortresses and villas","and all the buildings","without human warmth."],"day":"01-18","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"pitalice","title_hr":"Pitalice","title_en":"Questions","hr":["Ljeto zimi ode","u krajeve druge,","ugrijati djecu","nakon zime duge."],"en":["Summer, in the winter,","travels far away","to warm the children after","a long winter's stay."],"day":"01-19"},{"slug":"sto-je-drvo","title_hr":"Što je drvo","title_en":"What Is a Tree?","hr":["Pitala me kćerka mala:","„Reci, tata, što je drvo?“","Da ti kažem, dijete moje,","kao deblo dođe prvo."],"en":["Once my little daughter asked me:","\"Tell me, Daddy, what's a tree?\"","Let me tell you, child of mine:","first, the trunk is what you see."],"day":"01-20"},{"slug":"jucer-digla-baka","title_hr":"Jučer digla baka","title_en":"Yesterday Grandma Held Her Head High","hr":["Unuče je baki","dio njene sreće,","unuče je baki","bogatstvo najveće."],"en":["A grandchild, to Granny,","is part of her pleasure;","a grandchild, to Granny,","is her greatest treasure."],"day":"01-21"},{"slug":"stiglo-nam-i-vincekovo","title_hr":"Stiglo nam i Vincekovo","title_en":"Now St Vincent's Day Has Come","hr":["Stiglo nam je već i Vincekovo,","čokoti se dobrim vinom krste","i domaćom delicijom kite,","da bi loze bile, rodne, čvrste."],"en":["Now St Vincent's Day has come already:","vine-stocks christened with good wine, and dressed","all about with homemade delicacies,","so the vines stand firm and bear their best."],"day":"01-22","occ_hr":"Vincekovo · napisano na današnji dan, 2015.","occ_en":"St Vincent's Day · written on this day in 2015"},{"slug":"prijatelju-jozi-santaku","title_hr":"Prijatelju Jozi Šantaku","title_en":"To My Friend Jozo Šantak","hr":["U ravnini Podravine","rodila me moja mati,","mnogo znanja u djetinjstvu,","nije mogla meni dati."],"en":["In the Podravina lowland","it was there my mother bore me;","much of learning, in my childhood,","she could never set before me."],"day":"01-23","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"gripa","title_hr":"Gripa","title_en":"The Flu","hr":["Mali je šaran","gripu dobio.","Nos mu curi","i boli ga glava.","Bos je na kiši","i mrazu bio","i sada u mokroj","postelji spava."],"en":["The little carp","has caught the flu.","His nose is running,","he's got an aching head.","He went barefoot","in rain and frost, too,","and now he's sleeping","in a soggy bed."],"day":"01-24"},{"slug":"procvjetala-stara-lipa","title_hr":"Procvjetala stara lipa","title_en":"The Old Linden Is in Bloom","hr":["Godinama još će cvasti,","mirisni nam dati čaj.","Kad snijeg vije,","čaj se pije,","svima nam je tada raj."],"en":["Many years it still will flower,","give us fragrant linden tea.","When snow's blowing,","tea is flowing,","heaven then for you and me!"],"day":"01-25"},{"slug":"macin-rucak","title_hr":"Macin ručak","title_en":"Kitty's Lunch","hr":["Jutros kad je papala","naša maca mala,","mamica joj nije","partiklicu dala.","Od mlijeka je bila","sva mokra po bradi,","šapicom se brisala –","što drugo da radi?"],"en":["This morning, when she sat","to eat, our little cat,","Mummy didn't give her","a bib, and that was that!","Her chin was all dripping","with milk, through and through;","she wiped it with her paw:","what else could she do?"],"day":"01-26"},{"slug":"ne-placi","title_hr":"Ne plači!","title_en":"Don't Cry!","hr":["Nasmiješi se malo kad si pokraj mene.","Da nam slatka ljubav kao rijeka teče.","Zaboravi tugu i te bolne sjene.","Neka bude više u životu sreće."],"en":["Smile a little bit whenever you're with me,","so that our love may, like a river, sweetly flow.","Forget the grief, those painful shadows: let them be,","and let more happiness come to us as we go."],"day":"01-27","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"prva-zekina-zima","title_hr":"Prva Zekina zima","title_en":"Little Bunny's First Winter","hr":["Nešto čudno se događa,","vjetar vije, sniježak prši,","mali zeko šape gladi,","a studen mu štipa uši."],"en":["Something strange is going on:","wind is blowing, snow appears,","little bunny rubs his paws,","and the frost nips at his ears."],"day":"01-28"},{"slug":"kroz-valpovo-tece-karasica","title_hr":"Kroz Valpovo teče Karašica","title_en":"The Karašica Flows Through Valpovo","hr":["Noć Mjesecom obasjana cijela","i zvijezdama okićeno veče',","ja i moja Valpovčanka Jela,","Karašicu gledamo gdje teče."],"en":["The whole night's bathed in moonlight, far and wide,","the evening's decked with stars across the sky;","my Valpovo girl, my Jela, at my side,","we watch the Karašica flowing by."],"day":"01-29","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"ne-budi-me-majko-rano","title_hr":"Ne budi me, majko, rano","title_en":"Don't Wake Me Early, Mother","hr":["Ne budi me, majko, rano.","Još se nisam naspavao.","Kad mi draga u san dođe,","za te snove sve bih dao."],"en":["Mother, do not wake me early,","I am not yet done with sleeping.","When my love comes in my dreaming,","all I'd give those dreams for keeping."],"day":"01-30"},{"slug":"obitelji-nikolic","title_hr":"Obitelji Nikolić!","title_en":"To the Nikolić Family!","hr":["Bakino sunašce","kad se probudi:","pa zar ima nešto","ljepše, dragi ljudi."],"en":["Grandma's little sunshine","when he wakes, refreshed:","tell me, dear people,","what could be more blessed?"],"day":"01-31","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"most-po-kome-gazis","title_hr":"Most po kome gaziš","title_en":"The Bridge You Walk Across","hr":["Sada nosim života breme.","Most sam po kome gaziš.","A kada prođe naše vrijeme,","kasno će biti da me maziš."],"en":["Now I carry all of life's great weight,","I'm the bridge on which you tread;","and when our time has passed, it will be late,","too late for you to stroke my head."],"day":"02-01"},{"slug":"ljubav-i-bol","title_hr":"Ljubav i bol","title_en":"Love and Pain","hr":["Ljubav je davanje.","Ljubav je primanje.","I što više daješ,","to duže traje.","No, teško je trpjeti","nepravedne boli,","a još su teže,","kad ih zadaje","koga srce voli."],"en":["Love is giving.","Love is receiving.","And the more you give,","the longer it will stay.","But it's hard to suffer","pains that are not due,","and harder still","when they come your way","from one your heart loves true."],"day":"02-02"},{"slug":"pitalice","title_hr":"Pitalice","title_en":"Questions","hr":["Reci, gdje se zima","po ljetu smrzava","i pokaži krevet","u kojem snijeg spava."],"en":["Tell me, in the summer,","where does winter freeze?","Show me, too, the bed","where the snow sleeps, please."],"day":"02-03"},{"slug":"kada-ti-dosada-dusu-truje","title_hr":"Kada Ti dosada dušu truje","title_en":"When Boredom Poisons Your Soul","hr":["Kada Ti dosada dušu truje,","kada te mora iz snova budi,","kada Te očaj u životu snađe,","kada već misliš da tonu lađe,","pročitaj pjesme iz knjige ove,","pa će Ti radost ozariti snove."],"en":["When boredom is poisoning your soul,","when nightmares wake you up out of your dreams,","when in your life despair has gripped you tight,","when you believe your ships sink out of sight,","then read the poems in this book of mine,","and joy will make your dreams begin to shine."],"day":"02-04"},{"slug":"za-drustvo-prijatelja-starina","title_hr":"Za Društvo prijatelja starina","title_en":"For the Society of Friends of Antiquities","hr":["Za nas mladost više ne postoji,","jer smo časno mi DRUŠTVO STARINA,","trebali bi više se družiti,","to bi bila baš prava milina."],"en":["Youth for us is gone, it is no more,","we're the honoured Antiques' Club, it's clear;","we should get together more as friends,","that would be a real delight and cheer."],"day":"02-05","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"zima","title_hr":"Zima","title_en":"Winter","hr":["Došla zima.","Snijeg je pao,","pa krovove zatrpao.","Iz dimnjaka dim se vije,","kraj pećice hladno nije."],"en":["Winter came.","Down fell snow,","burying the roofs below.","From the chimney smoke curls high;","by the stove it's warm and dry."],"day":"02-06"},{"slug":"domovino-moja","title_hr":"Domovino moja","title_en":"My Homeland","hr":["I kad umrem ti ćeš dalje cvasti","i majčinski širit krila svoja.","Dok je tebe, Šokadijo, mila,","bit će dičnih ljudi i heroja!"],"en":["And when I die, you'll blossom on and on,","spreading wide your wings as mothers do;","while you live, my dear Šokadija,","there'll be worthy folk and heroes too!"],"day":"02-07","occ_hr":"napisano na današnji dan, 1997.","occ_en":"written on this day in 1997"},{"slug":"djetlic","title_hr":"Djetlić","title_en":"The Woodpecker","hr":["Jutros kad je kljucao","neki tvrdi dub,","maloga je djetlića","zabolio zub."],"en":["This morning, pecking at","a hard oak (tough job!),","the little woodpecker's","tooth began to throb."],"day":"02-08"},{"slug":"djeca-snjeska-napravila","title_hr":"Djeca snješka napravila","title_en":"The Children Made a Snowman","hr":["Došla zima, sniježak pršti","i dječici štipa uši.","Bijeli sniježak tiho pada,","to idila zimska vlada."],"en":["Winter's come, the snowflakes whirl,","nipping ears of boy and girl.","Softly falls the snow so white:","winter's idyll, pure delight."],"day":"02-09","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"moje-ce-te-oci-oplakati","title_hr":"Moje će te oči oplakati!","title_en":"My Eyes Will Weep for You!","hr":["Za svu sreću i tvoje poljupce.","Za svu ljubav, koju si mi dala,","za sve suze, moje radosnice,","riječ je mala da ti kažem hvala."],"en":["For all the joy we had, and all your kisses,","for all the love you gave, so full and free,","for all the tears I wept, my tears of gladness,","\"thank you\" is much too small a word from me."],"day":"02-10","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"ne-reci-da-me-volis","title_hr":"Ne reci da me voliš","title_en":"Don't Say You Love Me","hr":["Ne reci da me voliš,","to govore oči tvoje,","dok srce tvoje meni,","ljubavnu pjesmu poje."],"en":["Do not say that you love me,","it's your eyes that tell me so,","while for me your heart is singing","a love song, sweet and low."],"day":"02-11","occ_hr":"napisano na današnji dan, 1990.","occ_en":"written on this day in 1990"},{"slug":"prijatelju-glazbeniku","title_hr":"Prijatelju, glazbeniku!","title_en":"To My Friend, the Musician!","hr":["Od pjesnika umjetniku,","nek nam bude to na diku,","što stvaramo našim radom,","ovom svijetu ljepšu sliku."],"en":["Poet to an artist true:","let this be our pride: we two,","by our labour and our art,","give the world a lovelier view."],"day":"02-12","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"ima-li-sto-slade-od-meda","title_hr":"Ima li što slađe od meda","title_en":"Is There Anything Sweeter Than Honey","hr":["Ima li što slađe od meda,","kojega pčele roje?","Slađe mogu biti,","jedino usne tvoje."],"en":["Is there anything sweeter than honey","the swarming bees lay in store?","Sweeter can be only","your lips, and nothing more."],"day":"02-13"},{"slug":"kuca-u-masti","title_hr":"Kuća u mašti","title_en":"A House in My Imagination","hr":["U mašti gradim kuću.","Samo za nas dvoje,","da u njoj ostvarim","sve divne snove moje."],"en":["In fancy I am building","a house for just us two,","where all my lovely dreams","could, one by one, come true."],"day":"02-14","occ_hr":"Valentinovo · napisano na današnji dan, 1974.","occ_en":"Valentine's Day · written on this day in 1974"},{"slug":"sokacki-obicaji","title_hr":"Šokački običaji","title_en":"Šokac Customs","hr":["Volim prela, sijela, šokačke divane,","i maškare volim, kada se opreme,","svu ljepotu volim u svatovske dane,","divne običaje što žive kroz vrijeme."],"en":["I love prela, sijela, the Šokac yarns they spin,","I love the maškare, when dressed up they appear,","I love all the beauty when wedding days begin,","the wonderful customs still living year on year."],"day":"02-15"},{"slug":"zasto-covjek-nije-kao-dijete","title_hr":"Zašto čovjek nije kao dijete","title_en":"Why Is Man Not Like a Child","hr":["Zašto čovjek nije kao dijete","u čistoći svoje duše?","Zašto neki kad odrastu","sve vrline ljudske ruše?"],"en":["Why is man not like a child","in the pureness of his heart?","Why do some, when they are grown,","tear man's virtues all apart?"],"day":"02-16"},{"slug":"vrati-mi-snove","title_hr":"Vrati mi snove!","title_en":"Give Me Back My Dreams!","hr":["Vrati mi se danas,","da ne plačem sutra.","Bez ljubavi tvoje","tužna su mi jutra."],"en":["Come back to me today,","so I won't weep tomorrow.","Without your love, my mornings","are mornings full of sorrow."],"day":"02-17","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"djecji-snovi","title_hr":"Dječji snovi","title_en":"Children's Dreams","hr":["Čujte samo malog Vladu!","Dobio od svoga brata","s lješnjacima čokoladu","veliku k´o sobna vrata."],"en":["Listen, Vlado's gift's the star!","From his brother (what a score!):","a whole hazelnut chocolate bar","big as any bedroom door!"],"day":"02-18"},{"slug":"od-djetinjstva-do-starackih-dana","title_hr":"Od djetinjstva do staračkih dana","title_en":"From Childhood to Old Age","hr":["Proš'o Božić i godina Nova,","odjurio i Valentin sveti,","a godine na pleća se nižu,","jer nam život kao strijela leti."],"en":["Christmas gone, and gone the New Year, too,","and Saint Valentine has hurried past;","years keep piling up upon our shoulders,","for, just like an arrow, life flies fast."],"day":"02-19","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"snjezana","title_hr":"Snježana","title_en":"Snježana","hr":["Da li si od snježnih pahuljica","ili od perja rajske ptice?","Ili leptir krilima je nježno","milovao tvoje divno lice?"],"en":["Are you made of flakes of falling snow,","or of plumes from birds of paradise?","Or did a butterfly with gentle wings","stroke your face, so lovely to the eyes?"],"day":"02-20","occ_hr":"napisano na današnji dan, 1989.","occ_en":"written on this day in 1989"},{"slug":"da-spasimo-stare-obicaje","title_hr":"Da spasimo stare običaje","title_en":"Let Us Save the Old Customs","hr":["Kada zima dođe, bilo je veselo,","skupljale se cure s večeri na prelo.","Bećari bi došli curama na sijelo,","veselo je zimi bilo svako selo."],"en":["When the winter came, the fun was at its height:","girls would gather at the prelo every night,","bećars joined the girls' sijelo, to their delight,","every village, winter-long, a merry sight."],"day":"02-21"},{"slug":"uloga-zene-u-braku","title_hr":"Uloga žene u braku","title_en":"A Wife's Role in Marriage","hr":["Sto poslova žena u kući ima,","trči po cijeli dan.","Šije, pere, kuha, sprema,","dok je ne savlada san."],"en":["A hundred jobs at home the wife must do,","she's on the run all day long;","she sews, she washes, cooks and cleans,","till sleep has grown too strong."],"day":"02-22","occ_hr":"napisano na današnji dan, 2009.","occ_en":"written on this day in 2009"},{"slug":"zecic-ocalinko","title_hr":"Zečić Očalinko","title_en":"Specky the Bunny","hr":["Gledam jednog zečića,","naočale ima.","Zbog toga je, vjerujte,","mrkva bila kriva."],"en":["I see a little bunny","with glasses on his face;","believe me, it's the carrot","that's to blame in this case."],"day":"02-23"},{"slug":"jozi-dubrovicu","title_hr":"Jozi Dubroviću","title_en":"To Jozo Dubrović","hr":["Želim da nam knjiga ova","Divno prijateljstvo spaja.","Družiti se, ta ljepota,","Stvara ljudskoj duši sjaja."],"en":["May this book of ours, I pray,","bind us in a friendship fine.","Keeping company — such beauty —","makes the human spirit shine."],"day":"02-24","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"djeca-snjeska-napravila","title_hr":"Djeca snješka napravila","title_en":"The Children Made a Snowman","hr":["Pa je snješko tužan bio,","od tuge se rastopio.","Mrkva, ugljan, metla stoje:","što od snješka ostalo je."],"en":["Then the snowman grew so sad,","melted from the grief he had.","Carrot, coal and broom, all three,","are what's left for us to see."],"day":"02-25"},{"slug":"dva-potoka-dvije-rijeke","title_hr":"Dva potoka, dvije rijeke","title_en":"Two Streams, Two Rivers","hr":["Na svom putu u prirodi,","svaka voda teče vodi,","pa se tako sve po malo,","iz potoka rijeka rodi."],"en":["Out in nature, on it flows;","water on to water goes;","and so, gently, bit by bit,","from a stream a river grows."],"day":"02-26"},{"slug":"ljubav-nekada-i-sada","title_hr":"Ljubav nekada i sada","title_en":"Love Then and Now","hr":["Sada više ne kaže:","\"Oh, mužiću zdravo!\"","Već u bradu promrsi:","\"Odnio te đavo!\""],"en":["She no longer says,","\"Oh, hubby, hello!\"","She mutters low instead:","\"To the devil you go!\""],"day":"02-27"},{"slug":"visibaba","title_hr":"Visibaba","title_en":"The Snowdrop","hr":["Visibaba nježna, mala,","prevarila ljubičicu:","uzela je lopaticu","i snijeg bijeli razbacala,","prije nje je procvjetala."],"en":["Little snowdrop, frail and small,","played the violet a trick:","took a little shovel, quick,","flung away the white snowfall,","and bloomed before her, first of all."],"day":"02-28"},{"slug":"zbrkani-snovi","title_hr":"Zbrkani snovi","title_en":"Muddled Dreams","hr":["Slušajte me, djeco, sada:","probudih se jednog jutra,","mjesto zore suton pada –","mislim da je bilo sutra."],"en":["Listen, children, what I say:","I woke up one morning, when","dusk instead of dawn held sway;","I think it was tomorrow then."],"day":"02-29"},{"slug":"dragi-prijatelji","title_hr":"Dragi prijatelji!","title_en":"Dear Friends!","hr":["To drugarstvo koje traje,","da se nikad ne ugasi,","neka ova pjesma bude,","plamen da ju vječno spasi!"],"en":["This companionship that lasts,","so that it won't lose its light,","let this poem be the flame","that will keep it ever bright!"],"day":"03-01","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"sretan-ti-rodendan","title_hr":"Sretan ti rođendan","title_en":"Happy Birthday to You","hr":["U životu sretna bila","bez imalo tužne sjene.","A najljepše kad ti bude,","ti se onda sjeti mene."],"en":["May your life be glad and happy,","never shadowed, sorrow-free;","and when life is at its fairest,","then, my dear, remember me."],"day":"03-02","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"lastavica","title_hr":"Lastavica","title_en":"The Swallow","hr":["Lasto, ptico mila","proljeća vjesniče!","Jesi li umorna","od dugoga leta?","Volim tebe, lasto!","Ti mi nosiš sreće","i toplo proljeće.","Puno divno cvijeta."],"en":["Swallow, darling bird,","herald of the spring!","Are you tired out","from your lengthy flight?","How I love you, swallow!","You bring luck and cheer","and warm spring each year,","flowers fair and bright."],"day":"03-03"},{"slug":"majka","title_hr":"Majka","title_en":"Mother","hr":["Kada dijete noću plače,","iz snova kada se budi,","da čedu svome utjehu nađe,","majka ga svija na grudi."],"en":["When a child cries in the night,","waking from its dreams in fear,","to find comfort for her little one,","mother holds it to her bosom near."],"day":"03-04","occ_hr":"napisano na današnji dan, 1980.","occ_en":"written on this day in 1980"},{"slug":"uloga-zene-u-braku","title_hr":"Uloga žene u braku","title_en":"A Wife's Role in Marriage","hr":["Kada muža glava zaboli,","kada treba problem da riješi.","Žena je tu da mu utjehu pruži","i da ga nježno tješi."],"en":["When the husband's head begins to ache,","when some problem's weighing on his mind,","there's the wife, to give him consolation","and to soothe him, tender, soft and kind."],"day":"03-05"},{"slug":"sretna-proljeca","title_hr":"Sretna proljeća","title_en":"Happy Springtimes","hr":["Jednog dana ozari me sunce,","ozari me i sunce i sreća.","Poljupcima koje si mi dala,","sretna su mi svanula proljeća."],"en":["One day I was lit up by the sun,","lit up by the sun and by delight;","with the kisses that you gave to me,","happy springtimes dawned for me, so bright."],"day":"03-06"},{"slug":"sokadijo-moj-voljeni-kraju","title_hr":"Šokadijo moj voljeni kraju","title_en":"Šokadija, My Beloved Land","hr":["Slavonijo moj mirisni cvijetu,","najljepša si na čitavom svijetu.","Nikada te neću nikom dati,","vječito ću tebe svojom zvati."],"en":["Slavonia, my fragrant flower, you","are loveliest the whole wide world through;","I'll never give you up to others, never;","I'll call you mine, and only mine, forever."],"day":"03-07","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"zena","title_hr":"Žena","title_en":"Woman","hr":["Žena je najljepša bajka,","Kao sestra,","Kao supruga,","Kao majka."],"en":["Woman is the fairest tale in life,","as a sister,","as a mother,","as a wife."],"day":"03-08","occ_hr":"Dan žena","occ_en":"International Women's Day"},{"slug":"gliste","title_hr":"Gliste","title_en":"The Worms","hr":["Došle male gliste","kod šustera Riste","da cipele naruče –","je li je moguće?"],"en":["Little worms came crawling","to cobbler Risto, calling,","to order shoes: dear me,","how can such a thing be?"],"day":"03-09"},{"slug":"ima-li-sto-ljepse","title_hr":"Ima li što ljepše","title_en":"What Could Be More Lovely","hr":["Kada žena voli","i kada je voljena,","ona je Afrodita","svome Adonisu."],"en":["When a woman loves","and when she is loved,","she is Aphrodite","to her own Adonis."],"day":"03-10"},{"slug":"duga","title_hr":"Duga","title_en":"The Rainbow","hr":["Kad kiša pada","i sunce sije,","to oblak vodu","iz rijeke pije."],"en":["When rain is falling","and the sun's aglow,","the cloud drinks water","from the river below."],"day":"03-11"},{"slug":"izmedu-htjenja-i-mogucnosti","title_hr":"Između htjenja i mogućnosti","title_en":"Between Wanting and Being Able","hr":["Naša mladost najljepše je doba,","a ljubav je zato da se proba."],"en":["Of all our days, our youth's the very best,","and love is there for putting to the test."],"day":"03-12","occ_hr":"napisano na današnji dan, 2004.","occ_en":"written on this day in 2004"},{"slug":"seljacke-idile","title_hr":"Seljačke idile","title_en":"Village Idylls","hr":["Sviće zora i sunašce viri,","bez oblaka nebo čisto, plavo,","kroz dolinu lahor tiho piri,","za sjetvu je danas vrijeme pravo."],"en":["Dawn is breaking, sunlight peeps our way,","not a cloud, the sky is blue and bright,","through the valley gentle breezes play,","and for sowing now the time is right."],"day":"03-13"},{"slug":"haiku","title_hr":"Haiku","title_en":"Haiku","hr":["PROLJEĆE:","Zima dala pete,","topola baca perje,","klepeću rode."],"en":["Spring:","Winter's taken to its heels,","the poplar sheds its feathers,","the storks clack their bills."],"day":"03-14"},{"slug":"u-mom-narucju","title_hr":"U mom naručju","title_en":"In My Arms","hr":["Kad milujem tebe, draga,","meni ljepše sreće nije.","Proljetne mi ruže cvatu","i ljetno me sunce grije."],"en":["When I stroke you, oh, my darling,","sweeter joy is past my knowing;","roses of the spring are blooming,","and the summer sun is glowing."],"day":"03-15"},{"slug":"sjecanje-na-djetinjstvo","title_hr":"Sjećanje na djetinjstvo","title_en":"Remembering My Childhood","hr":["I sad kad se sjetim srce me zazebe.","Na svakom koraku, bijedu sam susreto.","Nikada se nisam stidio sam sebe,","jer poštenje meni bilo je presveto."],"en":["Remembering it now, a chill goes through my frame.","At every step I met with poverty and need;","yet I have never had to hang my head in shame,","for honesty to me was sacred, as a creed."],"day":"03-16","occ_hr":"napisano na današnji dan, 1976.","occ_en":"written on this day in 1976"},{"slug":"plavi-cvijete","title_hr":"Plavi cvijete","title_en":"My Blue Flower","hr":["Oči tvoje modre, snene,","kradom moje srce draže.","Usne slatke i vatrene,","poljubac od mene traže."],"en":["Your blue eyes, half-closed in dream,","slyly tease this heart of mine;","lips so sweet, with fire agleam,","for a kiss from me they pine."],"day":"03-17"},{"slug":"suha-kora-prove","title_hr":"Suha kora prove","title_en":"The Dry Crust of Cornbread","hr":["A kad shvatih tu razliku","među ljudstvom što se rađa.","I ta suha kora prove","bila mi je tada slađa."],"en":["And when I grasped the difference,","grown between the rich and poor,","even that dry cornbread crust","tasted sweeter than before."],"day":"03-18","occ_hr":"napisano na današnji dan, 1976.","occ_en":"written on this day in 1976"},{"slug":"pjesma-sinu","title_hr":"Pjesma sinu!","title_en":"A Poem for My Son!","hr":["Ti još i ne znaš, kako bi i znao,","koliko te moje biće silno voli,","kada budeš svoje čedo sinom zvao","tek ćeš onda znati za strepnje i boli."],"en":["You do not know it yet (and how could you have known)","how mightily my whole being loves you so;","but when you call a son of yours your very own,","then only will you know the dread, the pain, the woe."],"day":"03-19","occ_hr":"Josipovo, Dan očeva","occ_en":"St Joseph's Day, Father's Day"},{"slug":"na-poklon-osnovnoj-skoli-sopje","title_hr":"Na poklon Osnovnoj školi Sopje","title_en":"A Gift to the Sopje Primary School","hr":["Našoj školi darujem tu knjigu,","kao spomen mog djetinjstva znaci,","kroz te pjesme ja ostavljam sebe,","nek' je vide i budući đaci."],"en":["I give this book to our school to keep,","a keepsake of my childhood, as a sign;","in these poems here I leave myself behind:","may future pupils see me in each line."],"day":"03-20"},{"slug":"pjesnikova-zelja-2011","title_hr":"Pjesnikova želja","title_en":"The Poet's Wish","hr":["JA VAM DJECO DONOSIM PROLJEĆE","TOPLO VRIJEME I MIRISNO CVIJEĆE!"],"en":["DEAR CHILDREN, HERE'S THE SPRING I BRING TO YOU:","WARM WEATHER, AND SWEET-SCENTED FLOWERS TOO!"],"day":"03-21","occ_hr":"Svjetski dan poezije i prvi dan proljeća · napisano na današnji dan, 2011.","occ_en":"World Poetry Day, first day of spring · written on this day in 2011"},{"slug":"volim-te-draga","title_hr":"Volim te, draga","title_en":"I Love You, Darling","hr":["Kada mi cjelov daješ,","srsi mi tijelom prođu,","ko' leptiri, mali, nježni,","kada sa cvijeta dođu."],"en":["When you give a kiss to me,","shivers run through me, my dear,","like the butterflies, small, tender,","from a flower coming near."],"day":"03-22"},{"slug":"trac","title_hr":"Trač","title_en":"Gossip","hr":["Ja vas molim i ljudi i žene,","počistite ispred svoga praga,","ne tražite sad okolo vraga,","Ostavite vi na miru mene."],"en":["Men and women, this I do implore:","sweep before your own door, keep it clear,","don't go looking round for devils near,","leave me be in peace, I ask no more."],"day":"03-23"},{"slug":"odgovor-drenovcanke","title_hr":"Odgovor Drenovčanke","title_en":"The Drenovci Woman's Reply","hr":["Reći ću ti što bih htjela:","da polako život teče,","u životu mome bolnom,","puno zdravlja, malo sreće."],"en":["I will tell you what I'd want:","that my life flow on at leisure,","and, in all my life of pain,","lots of health, of joy a measure."],"day":"03-24","occ_hr":"napisano na današnji dan, 2007.","occ_en":"written on this day in 2007"},{"slug":"ljubicice","title_hr":"Ljubičice","title_en":"Violets","hr":["Kao dio neba,","kao oči tvoje,","ljubičice plave","kraj puteljka stoje."],"en":["Like a piece of the sky","and like your eyes, too,","beside the path there stand","the violets of blue."],"day":"03-25"},{"slug":"sretna-proljeca","title_hr":"Sretna proljeća","title_en":"Happy Springtimes","hr":["Ne znam gdje si do sad bila, draga.","Da l' pod snijegom k'o ljubica mala?","Zbog ljepote te čarobne noći,","ti si meni svoju ljubav dala."],"en":["I don't know where you have been, my dear —","under snow, a violet, could it be?","For the beauty of that magic night","you have given all your love to me."],"day":"03-26"},{"slug":"moja-velika-otkrica","title_hr":"Moja velika otkrića","title_en":"My Great Discoveries","hr":["Htio sam svijetu","sve najbolje dati,","al´ me nije moja","razumjela mati."],"en":["I wanted to give","the world all that's good,","but my own mother","never understood."],"day":"03-27"},{"slug":"valpovacke-poete","title_hr":"Valpovačke poete","title_en":"Valpovo's Poets","hr":["Kad napiše svoju knjigu,","pjesniku je svakom dika","pa i onda, kad ga nema,","ostala je časna slika."],"en":["When he's written his own book,","every poet feels the pride;","even when he's gone from us,","his honoured image will abide."],"day":"03-28","occ_hr":"napisano na današnji dan, 2007.","occ_en":"written on this day in 2007"},{"slug":"proljece","title_hr":"Proljeće","title_en":"Spring","hr":["Okopnio snijeg,","proljeće je stiglo.","Sluti se toplina sunca.","Trava polako rosu pije,","djetlić već drvo kljuca."],"en":["The snow has thawed away,","and spring is here at last.","You feel the warmth of the sun.","The grass drinks slowly of the dew,","the woodpecker's tapping has begun."],"day":"03-29"},{"slug":"kitisanci","title_hr":"Kitišanci","title_en":"Kitišanci","hr":["Oh, posveti, Bože ruke,","koje su ti hram dizali,","da bi naša pokoljenja,","za blagoslov božji znali."],"en":["Sanctify, O God, the hands","that have raised this house to you,","so that all our generations","may come to know God's blessing too."],"day":"03-30"},{"slug":"slikar-zeko","title_hr":"Slikar zeko","title_en":"Bunny the Painter","hr":["Jutros se u dvorištu","digla strašna graja,","jer netko je kokicama","ofarbao jaja."],"en":["In the yard this very morning","such a racket rose:","someone painted all the hens' eggs,","who, nobody knows!"],"day":"03-31"},{"slug":"moj-voljeni-grade","title_hr":"Moj voljeni grade","title_en":"My Beloved Town","hr":["Poj slavuja budio te zorom,","sa platana tvoga perivoja,","odjek zvona sa crkvenog tornja,","donio ti san noćnog spokoja."],"en":["May the nightingale's song wake you at dawn","from the plane trees standing in your park,","and the church bells' echo from the tower","bring you peaceful sleep when night grows dark."],"day":"04-01"},{"slug":"jeka","title_hr":"Jeka","title_en":"Echo","hr":["Volim te, volim te, volim!","Taj odjek divne jeke,","u srcu mi snažno bruji,","k'o žubor gorske rijeke."],"en":["I love you, love you, love you!","That lovely echo's ring","keeps humming in my heart","like a murmuring mountain spring."],"day":"04-02","occ_hr":"napisano na današnji dan, 1979.","occ_en":"written on this day in 1979"},{"slug":"maslacak","title_hr":"Maslačak","title_en":"The Dandelion","hr":["Procvao maslačak","žuti se u travi,","a kasnije nosi","pahulje na glavi."],"en":["The dandelion's blooming,","yellow in the grass,","and fluff sits on its head","later, as days pass."],"day":"04-03"},{"slug":"zivot-penzionera","title_hr":"Život penzionera","title_en":"A Pensioner's Life","hr":["A izbori kada prođu,","nastavlja se priča stara.","Penzioner k'o i prije","mali je k'o bubamara."],"en":["When elections have gone by,","back comes the old tale, word for word:","and the pensioner, as ever,","is as small as a ladybird."],"day":"04-04","occ_hr":"napisano na današnji dan, 1992.","occ_en":"written on this day in 1992"},{"slug":"mala-skola","title_hr":"Mala škola","title_en":"The Little School","hr":["Proljeće je stiglo","preko brda dola,","počela je s radom","prava mala škola."],"en":["Spring has come along","over hill and dell;","a real little school","has started up as well."],"day":"04-05"},{"slug":"brodolomac","title_hr":"Brodolomac","title_en":"The Castaway","hr":["Ja opet živim, gledam žarko sunce","i jutarnju rosu kako trava pije.","I dalje moje spavalo bi srce,","da ga tvoja ljubav probudila nije."],"en":["I live again; I see the burning sun on high","and how the thirsty grass drinks up the morning dew;","and to this day my heart in slumber still would lie,","if your love had not come and woken it anew."],"day":"04-06","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"kalendar","title_hr":"Kalendar","title_en":"The Calendar","hr":["U ožujku visibaba","ispod snijega izviruje.","U travnju već trava raste","i cvrkut se ptica čuje."],"en":["March, and there's the snowdrop peeping","out from underneath the snow.","April, and the grass is growing,","birds are chirping, high and low."],"day":"04-07"},{"slug":"za-uskrs-se-farba-jaje","title_hr":"Za Uskrs se farba jaje","title_en":"At Easter We Dye the Eggs","hr":["Eto nam se Uskrs javlja,","bit će dječici veselja,","jaja ćemo ofarbati,","to je naša draga želja."],"en":["Easter's here, it's come to call,","little children will be glad;","we'll be dyeing eggs, the dearest","wish that we have ever had."],"day":"04-08","occ_hr":"uskrsno vrijeme","occ_en":"Eastertide"},{"slug":"sokacki-obicaji","title_hr":"Šokački običaji","title_en":"Šokac Customs","hr":["Volim kad se ljubav sokacima vodi.","Volim škripu đerma i seosku viku.","Volim kada mjesec sa zvijezdama hodi,","na toj mjesečini volim svoju diku."],"en":["I love when the lanes see the lovers go by,","I love the well-sweep's creaking, the village's call,","I love when the moon strolls with stars through the sky,","in that moonlight I love my sweetheart best of all."],"day":"04-09","occ_hr":"napisano na današnji dan, 1994.","occ_en":"written on this day in 1994"},{"slug":"postovani-prijatelju","title_hr":"Poštovani prijatelju!","title_en":"Dear Friend!","hr":["U proljeće mnoge žabe,","u bari su kreketale.","Da se riješi žablji problem,","sastanak su održale."],"en":["In the springtime, many frogs","croaked there in the pond all day;","to resolve the frogs' dilemma","they held a meeting right away."],"day":"04-10"},{"slug":"sve-se-caje-okupise","title_hr":"Sve se \"Čaje\" okupiše","title_en":"All of Čaje Gathered Here","hr":["Kad svirači zasviraju znano,","NE BUDI ME, MAJKO, TAKO RANO,","To mi vrati onu ljubav staru,","pa zaigra srce u bećaru."],"en":["When players strike that tune so widely known,","\"DON'T WAKE ME EARLY, MOTHER\", all my own,","it brings me back that old love from before,","and then the bećar's heart will dance once more."],"day":"04-11","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"proljece","title_hr":"Proljeće","title_en":"Spring","hr":["Zatim u žaru zapadu ide","još jedan proljetni dan.","Zvijezde na nebu","već se pale,","slatki nam donose san."],"en":["Then off into the glowing west","goes one more day of spring.","The stars up in the sky","are lighting up,","and sweet sleep to us they bring."],"day":"04-12"},{"slug":"pod-granama-jorgovana","title_hr":"Pod granama jorgovana","title_en":"Beneath the Lilac Boughs","hr":["Pod granama jorgovana,","u zvjezdanoj tihoj noći,","dok je ruža mirisala,","ljubio sam tvoje oči."],"en":["Underneath the lilac branches,","in the hush of starlit splendour,","while the rose was breathing fragrance,","your dear eyes I kissed so tender."],"day":"04-13"},{"slug":"slikar-zeko","title_hr":"Slikar zeko","title_en":"Bunny the Painter","hr":["Mislim da je svima jasno","tko je majstor bio.","Eto, djeco, to je zeko","jaja obojio."],"en":["I think everyone can see","who the master was today:","there, dear children, it was bunny","who had painted them that way!"],"day":"04-14"},{"slug":"seljacke-idile","title_hr":"Seljačke idile","title_en":"Village Idylls","hr":["Uranio Šokac u svitanje,","ormu sprema i dorate preže.","Spremio se, ide na oranje,","taj ga nagon od djetinjstva veže."],"en":["At the break of day the Šokac rose,","gets the harness, hitches up the bays;","ready now, off to the plough he goes,","drawn by instinct since his boyhood days."],"day":"04-15"},{"slug":"kad-ispuni-televizor-zelje","title_hr":"Kad ispuni televizor želje","title_en":"When the Television Grants Wishes","hr":["Cecilija subotu ukrasi,","i programu svu ljepotu daje,","svaki žamor u kući se gasi,","u grudima sva milina traje."],"en":["Cecilija adorns our Saturday","and gives all its beauty to the show;","in the house each murmur dies away,","in our hearts the sweetness stays aglow."],"day":"04-16","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"etno-kuca-semialjac-kate","title_hr":"Etno kuća Semialjac Kate","title_en":"Kata Semialjac's Ethno House","hr":["Iza štaglja predivna ljepota,","zrak miriše, procvalo je voće,","noć je topla, divna mjesečina,","a zvijezde su okitile veče'."],"en":["Behind the barn, a loveliness so rare:","the air is sweet, the fruit trees are in flower,","the night is warm, the moonlight is divine,","and all the stars have decked the evening hour."],"day":"04-17"},{"slug":"lijepo-je-biti-voljen","title_hr":"Lijepo je biti voljen","title_en":"It's Lovely to Be Loved","hr":["Lijepo je biti voljen","i kada iskreno ljubiš.","Kada svoje tople usne","voljenom biću nudiš."],"en":["It is lovely to be loved,","and to love sincerely too,","when you offer your warm lips","to the one who's loved by you."],"day":"04-18"},{"slug":"kornjaca","title_hr":"Kornjača","title_en":"The Tortoise","hr":["Upregla se kornjača","u vlastita kola,","pa ih sama vuče","mjesto starog vola."],"en":["The tortoise has harnessed","herself to her cart;","she pulls it alone","and plays the old ox's part."],"day":"04-19"},{"slug":"zenske-suze","title_hr":"Ženske suze!","title_en":"A Woman's Tears!","hr":["Prošlo djetinjstvo,","došla mladost bujna,","osvanulo proljeće,","dan ljubavi","i zora rujna."],"en":["Childhood passed away,","youth came, lush and bright,","and at last the springtime dawned,","a day of love","and a dawn of rosy light."],"day":"04-20"},{"slug":"kratki-dani","title_hr":"Kratki dani","title_en":"Short Days","hr":["Blagi pogled oka tvoga","i obrazi nježni tvoji,","kad ih ljubim, cvijete mili,","prekratki su dani moji."],"en":["Gentle glances of your eyes","and your cheeks so soft and fine:","when I kiss them, darling flower,","all too short these days of mine."],"day":"04-21","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"sto-je-ljubav","title_hr":"Što je ljubav?","title_en":"What Is Love?","hr":["Ljubav je,","vjetrom nošen","lutajući brod,","koji muškarca vodi","u bračnu luku.","Kad progleda,","tek tada vidi","da je nasukan."],"en":["Love is","a drifting ship,","borne by the wind,","that carries a man","into wedlock's harbour.","When his eyes open,","only then does he see","that he has run aground."],"day":"04-22","occ_hr":"napisano na današnji dan, 1997.","occ_en":"written on this day in 1997"},{"slug":"sto-je-drvo","title_hr":"Što je drvo","title_en":"What Is a Tree?","hr":["Kad proljetno sunce grane,","svako drvo tad procvjeta","i opojni miris širi,","što je ukras ovog svijeta."],"en":["When the sun of spring shines down,","every tree blooms, full of grace,","spreading heady scent around","to adorn this earthly place."],"day":"04-23"},{"slug":"slavonija","title_hr":"Slavonija","title_en":"Slavonia","hr":["U edenu tom zemaljskom,","eto, tu sam rođen i ja.","Tu življahu moji preci:","to je moja Slavonija!"],"en":["In this earthly Eden, see,","here I too was born and grown;","here my forefathers once lived:","this is my Slavonia, my own!"],"day":"04-24"},{"slug":"moja-djevojka","title_hr":"Moja djevojka","title_en":"My Girl","hr":["Usne joj crvena trešnja,","a lice trešnjin cvijet.","Kad ljubim usne njene,","kao da pijem med."],"en":["Her lips are ripe red cherries,","her face, like cherry blossom, white;","and when I kiss her lips,","it's honey and delight."],"day":"04-25"},{"slug":"oj-dodo-oj-dodole","title_hr":"Oj, dodo, oj, dodole","title_en":"Oj, Dodo, Oj, Dodole","hr":["Daj nam, Bože, kiše malo,","da natopi žedno polje,","da se malo živi bolje."],"en":["Give us, Lord, a little rain,","soak the dry and thirsty ground,","so we'll live better all around."],"day":"04-26","occ_hr":"napisano na današnji dan, 1998.","occ_en":"written on this day in 1998"},{"slug":"jutarnji-problemi","title_hr":"Jutarnji problemi","title_en":"Morning Troubles","hr":["Dok djeca spavaju,","cipelice ustaju,","po dvorištu trče","i loptu šutaju."],"en":["While all the children snore,","the shoes hop down to the floor,","they race around the yard","and kick a ball, and score!"],"day":"04-27"},{"slug":"lastina-kuca","title_hr":"Lastina kuća","title_en":"The Swallow's House","hr":["U svako pramaljeće","nama se laste jave.","Gnijezdo kad brižno srede,","jaja u njega stave."],"en":["Every year, in early spring,","swallows come to us again;","when with care they've fixed the nest,","they lay eggs inside it then."],"day":"04-28"},{"slug":"dravsko-proljece","title_hr":"Dravsko proljeće","title_en":"Drava Spring","hr":["Tridesetog travnja Sopje","spretno veze kolo sreće,","jer Sopjani toga dana","slave „DRAVSKO PRAMALJEĆE“."],"en":["On the thirtieth of April","Sopje weaves a joyful ring,","for upon that day its people","celebrate the \"Drava Spring\"."],"day":"04-29","occ_hr":"uoči Dravskog proljeća u Sopju","occ_en":"eve of the Drava Spring festival in Sopje"},{"slug":"sretan-ti-rodendan-sine","title_hr":"Sretan ti rođendan, sine!","title_en":"Happy Birthday, Son!","hr":["Ne saznao nikada za tugu.","Sve u sreći i bez bolnih rana,","s najdražima svoje obitelji,","proslavio mnogo rođendana."],"en":["May you never come to know of sorrow;","all in happiness, and free of pain,","with the dearest of your family","may you see many birthdays come again."],"day":"04-30","occ_hr":"Rođendan sina","occ_en":"His son's birthday"},{"slug":"lopata-i-kramp","title_hr":"Lopata i kramp","title_en":"The Shovel and the Pick","hr":["Lopata i stari kramp,","svakog dana složno rade:","zajednički cestu grade,","često puta trnje vade,","a ponekad ruže sade.","A sve rade bez nagrade!"],"en":["Shovel and the old pickaxe","work together every day:","build the road and pave the way,","often clear the thorns away,","and plant roses in the clay.","And they do it all without pay!"],"day":"05-01","occ_hr":"Praznik rada","occ_en":"Labour Day"},{"slug":"nek-se-slavi-u-sopju-veselje","title_hr":"Nek' se slavi u Sopju veselje","title_en":"Let Sopje Celebrate and Make Merry","hr":["U proljeće MAJIPANI se sade,","to mladići znak curama daju,","jer ujesen svatovi se prave,","neka budu spremne za udaju."],"en":["Springtime sees the maypoles in the ground:","that's how lads tell girls what's on the way,","for when autumn's weddings come around,","let the girls be ready for that day."],"day":"05-02"},{"slug":"proljece","title_hr":"Proljeće","title_en":"Spring","hr":["Mušice lete i pčele zuje,","posvuda miriše cvijet.","Da ptićima svojim","hranu nađu,","krenule laste na let."],"en":["Gnats are flying, bees are buzzing,","sweet scent of flowers everywhere.","To find the food","their nestlings need,","the swallows soar into the air."],"day":"05-03"},{"slug":"dakovo-je-biser-slavonije","title_hr":"Đakovo je biser Slavonije","title_en":"Đakovo Is the Pearl of Slavonia","hr":["Slavonijo, domovino moja,","volim tebe k'o majčino krilo.","Od davnina naselja te krase,","u središtu Đakovo se svilo."],"en":["O Slavonia, my own homeland,","like my mother's lap I love you best;","since of old your villages adorn you,","at your centre Đakovo made its nest."],"day":"05-04"},{"slug":"osa","title_hr":"Osa","title_en":"The Wasp","hr":["Kao zumbul plavi","miriše joj kosa.","Ja sletoh na cvjetak","i postadoh osa."],"en":["Her hair has the scent","of a hyacinth blue;","I lit on the blossom,","and a wasp I grew."],"day":"05-05"},{"slug":"duga","title_hr":"Duga","title_en":"The Rainbow","hr":["Jeste li vidjeli","na nebu dugu,","onu divnu","šarenu prugu?"],"en":["Have you ever seen","the rainbow in the sky,","that lovely stripe","of colours, way up high?"],"day":"05-06"},{"slug":"kratki-dani","title_hr":"Kratki dani","title_en":"Short Days","hr":["Usne tvoje tople, meke,","kao perje ptice rajske.","U krilu se tvome topim,","k'o jutarnje rose majske."],"en":["Your warm lips are soft as feathers","of a bird of paradise;","in your lap I melt away","like the dew when May suns rise."],"day":"05-07"},{"slug":"san-o-sreci","title_hr":"San o sreći","title_en":"A Dream of Happiness","hr":["Budila me moja majka,","svako jutro zorimice","i suzama svojim toplim,","umivala moje lice."],"en":["My own mother used to wake me","every morning, at dawn's first trace,","and with her own tears, so warm,","she would wash my little face."],"day":"05-08"},{"slug":"klokan","title_hr":"Klokan","title_en":"The Kangaroo","hr":["Klokana nježnog, malog,","kad rujna zora zarudi,","dok u toploj torbi spava,","majčino srce budi."],"en":["The tender little kangaroo,","when the dawn is blushing red,","is woken by his mother's heart","sleeping in his warm pouch-bed."],"day":"05-09"},{"slug":"majka","title_hr":"Majka","title_en":"Mother","hr":["Za svaku bolest čeda svoga,","majčino srce pati.","Svoje bi oči za njega dala.","To može samo mati."],"en":["For each illness of her little one","a mother's heart aches through and through.","She would give her very eyes for it:","that, a mother alone can do."],"day":"05-10","occ_hr":"Majčin dan (svibanj)","occ_en":"Mother's Day (May)"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["I starost je polako već stigla,","barem da je zdravlje malo bolje.","Sada čekam na rajska blaženstva,","vjerujte mi, protiv svoje volje."],"en":["Old age has slowly come to me as well;","if only I were not so often ill!","Now I await the blessed joys of heaven —","believe me, friends, against my very will."],"day":"05-11","occ_hr":"Obljetnica pjesnikove smrti (2015.)","occ_en":"Anniversary of the poet's death (2015)"},{"slug":"mali-ivica","title_hr":"Mali Ivica","title_en":"Little Ivica","hr":["Pa mu sada mama","nos i usta miva,","njemu mrlja žao","i plače za njima!"],"en":["Now his mummy's washing","the smudges all away,","but he's sorry for them","and cries for them to stay!"],"day":"05-12"},{"slug":"sjecanje-na-djetinjstvo","title_hr":"Sjećanje na djetinjstvo","title_en":"Remembering My Childhood","hr":["Koru suhe prove svaki dan sam grizo.","Da se može bolje, nisam mog'o znati,","ipak nisam nikom u životu gmiz'o.","Tako me je moja naučila mati."],"en":["A crust of dry cornbread I gnawed on every day;","that life could be much better, I could never know,","yet all my life I've crawled to no one on my way:","and that is how my mother taught me, long ago."],"day":"05-13"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["Tu kolijevka stoji u buđaku,","dične ljude ona je zibala,","pokoljenja mnoga iznjedrila,","dok im majka pjesmicu pjevala."],"en":["The cradle stands there in its corner nook,","it rocked fine folk to sleep in days gone by,","brought forth so many generations, while","their mother sang to them a lullaby."],"day":"05-14"},{"slug":"netaknuta-ruza","title_hr":"Netaknuta ruža","title_en":"The Untouched Rose","hr":["Uzmi od života ono što je tvoje,","jer za sretnu ljubav trebaju tek dvoje."],"en":["So take from life whatever's yours, whatever's due,","for happy love, my dear, all that it takes is two."],"day":"05-15"},{"slug":"u-veselom-drustvu","title_hr":"U veselom društvu","title_en":"In Merry Company","hr":["\"Oprostite ima l'","tu mjesta za mene?","Ne samo za stolom,","već u srcu vašem.\"","I još sam ja htio","nešto da joj kažem,","ali kakav pogled","nepoznate žene."],"en":["\"Pardon me, is there","a place for me that's free?","Not just at your table,","but within your heart.\"","I wanted to say more,","I'd only made a start,","but what a look that lady,","a stranger, gave to me!"],"day":"05-16"},{"slug":"na-cimenu-sokacko-veselje","title_hr":"Na Čimenu Šokačko veselje","title_en":"Šokac Merriment on the Čimen","hr":["Tu se skuplja Šokadija mlada","biser naše Slavonije ravne","da prikažu svu ljepotu sada","uspomene iz prošlosti davne."],"en":["Here the young Šokadija comes today,","pearl of our Slavonia's level plain,","setting all its beauty on display,","bringing distant memories back again."],"day":"05-17","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"sreca","title_hr":"Sreća","title_en":"Happiness","hr":["Male su ti i planete,","misli među zvijezde lete.","U ljubavi kad je sreće","i sunce se rađa veće."],"en":["Even planets seem too slight,","thoughts among the stars take flight;","when there's happiness in love,","larger dawns the sun above."],"day":"05-18"},{"slug":"hodi-mjesece-zvijezdama","title_hr":"Hodi, mjeseče, zvijezdama","title_en":"Walk, O Moon, Among the Stars","hr":["Hodi, mjeseče, zvijezdama,","potraži Danicu svoju.","Ugasi fenjer večeras,","dok ljubim voljenu moju."],"en":["Walk, O moon, among the stars,","seek your Danica, your own;","put your lantern out tonight","while I kiss my love alone."],"day":"05-19"},{"slug":"dravsko-proljece","title_hr":"Dravsko proljeće","title_en":"Drava Spring","hr":["Kad se kolo zavijori,","noge pletu, sve se praši.","Tankovito cura vrisne,","običaji to su naši."],"en":["When the kolo swirls and flutters,","feet are weaving, dust flies high;","shrill and thin a girl cries out:","these are customs we live by."],"day":"05-20"},{"slug":"pored-nase-rijeke","title_hr":"Pored naše rijeke","title_en":"Beside Our River","hr":["Od kada se nismo vidjeli nas dvoje?","Možda te sad više prepoznao ne bi'?","Godine su duge učinile svoje,","a nekada mio bio sam ja tebi."],"en":["How long since last we saw each other, we two?","Would I still know you now, if we should meet again?","The long years that have passed have done what years will do,","and once I used to be so dear to you, back then."],"day":"05-21"},{"slug":"diljem-slavonije","title_hr":"Diljem Slavonije","title_en":"All Across Slavonia","hr":["Ja sam rođen u blizini Drave,","u dolini polja i livada,","okoline Podravske Slatine,","Šokica me porodila mlada."],"en":["I was born close to the Drava river,","in a vale of fields and meadows fair,","round about Podravska Slatina,","and a young Šokica bore me there."],"day":"05-22"},{"slug":"zaspalo-mace","title_hr":"Zaspalo mače","title_en":"The Sleeping Kitten","hr":["Naša maca, kada spava,","miče šapom, brkom,","valjda miša tada sanja","i hvata ga trkom."],"en":["When our kitty is asleep,","paw and whiskers flick;","she must dream about a mouse,","catching it so quick!"],"day":"05-23"},{"slug":"hej-zivote","title_hr":"Hej živote","title_en":"Hey There, Life","hr":["Svim ljudima ovog svijeta,","da im grana mira cvijeta!","Ljudski razum da ne gube,","da se kao braća ljube!"],"en":["To all people, near and far,","may peace blossom where they are!","May they keep a human mind,","love like brothers, warm and kind!"],"day":"05-24","occ_hr":"napisano na današnji dan, 1993.","occ_en":"written on this day in 1993"},{"slug":"ja-i-moj-medas-josip","title_hr":"Ja i moj međaš Josip","title_en":"Me and My Neighbour Josip","hr":["Stigli su nam i trenuci sreće,","došlo vrijeme da se kući kreće.","Domovino predivna i mila,","uvijek si mi ti na srcu bila."],"en":["Moments of good fortune came our way;","time had come to head for home to stay.","Homeland, lovely, dear beyond compare,","in my heart you always have been there."],"day":"05-25"},{"slug":"dodi-na-moje-grudi","title_hr":"Dođi na moje grudi","title_en":"Come and Lie Upon My Breast","hr":["Kada djeca odrastu i odu","i život te izmuči kruti,","da svome bolu utjehu nađeš,","dođi na moje grudi!"],"en":["When the children grow and leave us","and harsh life has you distressed,","so your pain may find its comfort,","come and lie upon my breast!"],"day":"05-26"},{"slug":"urednice-info-valpovstine","title_hr":"Uredniče Info Valpovštine","title_en":"To the Editor of INFO Valpovštine","hr":["Ja ću dalje stih pisati","i ljepotu puku dati."],"en":["I'll keep writing verses, then,","bringing beauty to my fellow men."],"day":"05-27","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"sva-godisnja-doba","title_hr":"Sva godišnja doba","title_en":"All the Seasons","hr":["Kada sam te sreo uz mirisno cvijeće,","zadrhtaše strune od osmijeha tvoga.","Za mene je bilo zeleno proljeće.","S tobom mi je sreća došla dana toga."],"en":["When I met you where the fragrant flowers grew,","at your smile the strings began to tremble so;","for me it was the springtime, green and new;","that day with you my happiness began to grow."],"day":"05-28"},{"slug":"podravino-diko-moja","title_hr":"Podravino, diko moja","title_en":"Podravina, My Pride","hr":["Još te volim, rodni kraju,","meni treba ljubav tvoja.","Eh, da mogu prošlost vratiti,","Podravino, diko moja!"],"en":["Still I love you, native land,","and I need you by my side.","Ah, if I could bring the past back,","O Podravina, my pride!"],"day":"05-29"},{"slug":"hrvatski-ponos","title_hr":"Hrvatski ponos","title_en":"Croatian Pride","hr":["Ja sam Hrvat, to morate znati,","jer hrvatska rodila me mati","i sa svojim mlijekom nadojila,","u hrvatskom duhu odgajala."],"en":["I am a Croat, this you ought to know,","born of a Croat mother long ago;","and with her milk she nursed me as I grew,","and reared me in the Croatian spirit too."],"day":"05-30","occ_hr":"Dan državnosti","occ_en":"Statehood Day"},{"slug":"ljubav-se-ne-mjeri","title_hr":"Ljubav se ne mjeri","title_en":"Love Is Not Measured","hr":["Ne mogu ti reći koliko te volim,","jer se ljubav, dušo, ne mjeri aršinom.","Od ljubavi tvoje i tvog milovanja,","kao da sam sasvim opijen sa vinom."],"en":["I cannot tell you, darling, just how much I love you,","for love is not a thing a yardstick can define;","from all your love for me and all of your caresses,","it is as if I'm drunk, completely drunk, on wine."],"day":"05-31"},{"slug":"ima-li-sto-ljepse-od-djeteta","title_hr":"Ima li što ljepše od djeteta","title_en":"Is There Anything Lovelier Than a Child","hr":["Ima li što ljepše od djeteta,","tako nježnog, malenog stvora!?","Kada kraj tebe nespretno puzi,","kada ti guče umjesto govora."],"en":["Is anything more lovely than a child,","a creature so tender and so small!?","When clumsily it crawls beside you there,","when it just coos to you, with no words at all."],"day":"06-01","occ_hr":"Međunarodni dan djeteta","occ_en":"International Children's Day"},{"slug":"ribar","title_hr":"Ribar","title_en":"The Fisherman","hr":["S valima se vjetar","nježno poigrava.","Negdje cvrčak cvrči,","u travi se skriva.","Dok se magla diže,","topola se njiše.","Dotle svaki ribar","vel'ku ribu sniva."],"en":["The wind is gently playing","with the little waves;","somewhere a cricket's chirping,","hid where the grasses swish;","and while the mist ascends,","the poplar sways and bends;","and every angler, meanwhile,","dreams of a great big fish."],"day":"06-02"},{"slug":"rascvjetano-ljeto","title_hr":"Rascvjetano ljeto","title_en":"Summer in Full Bloom","hr":["Oko nas je rascvjetano ljeto.","Sunce grije i nebo se plavi,","a nas dvoje, dva malena cvijeta,","ostali smo ležati u travi."],"en":["All around us, summer was in bloom,","warm the sun, the sky above so blue,","and the two of us, two little flowers,","lay on in the grass the whole day through."],"day":"06-03"},{"slug":"beliscanski-kotlic-mali","title_hr":"Belišćanski kotlić mali","title_en":"The Little Cauldron of Belišće","hr":["Poželimo tom kotliću","da mu grana mira cvjeta,","nek' čobanac dobar kuha","i nahrani pola svijeta!"],"en":["Let us wish this cauldron well:","may its peace-branch bloom and spread;","may it cook a good čobanac","and see half the world well fed!"],"day":"06-04","occ_hr":"napisano na današnji dan, 2005.","occ_en":"written on this day in 2005"},{"slug":"bara","title_hr":"Bara","title_en":"The Pond","hr":["Na njenom drveću","ptičice ćurliču,","djeca se u bari","kupaju i viču."],"en":["On its trees the birdies","twitter all about;","in the pond the children","bathe and splash and shout."],"day":"06-05"},{"slug":"podaci-o-pjesniku","title_hr":"Podaci o pjesniku","title_en":"Particulars of the Poet","hr":["Ja ne skrbim kruh u znoju,","mirovinu imam svoju.","I kućicu svoju imam,","pa u noći divno snivam,","preko dana u njoj dišem","i tu svoje pjesme pišem."],"en":["I no longer sweat for bread,","I've my pension now instead.","And my little house is mine,","where at night I dream so fine;","there by day I breathe and dwell,","there I write my poems as well."],"day":"06-06"},{"slug":"pjesma-valpovu","title_hr":"Pjesma Valpovu","title_en":"A Poem for Valpovo","hr":["Tek u ljetu kad sunce zažeže,","zlatnog klasja puna je dolina.","Sve je ravno dokle oko seže,","to bogatstvo gledat je milina."],"en":["When the summer sun begins to blaze,","golden wheat-ears fill the valley plain;","flat the land as far as eye can gaze:","what a joy to see such wealth of grain!"],"day":"06-07"},{"slug":"pace-2","title_hr":"Pače","title_en":"The Duckling","hr":["Malo pače,","kada jede,","očima koluta,","zatim brzo vodu pije","da lakše proguta!"],"en":["Little duckling,","when it eats,","rolls its eyes and blinks,","then, to help the food go down,","quickly sips and drinks!"],"day":"06-08"},{"slug":"haiku","title_hr":"Haiku","title_en":"Haiku","hr":["OLUJA:","Oblaci plaču,","zvijezda vara mjeseca,","gromovi ječe."],"en":["Storm:","The clouds are weeping,","a star is cheating on the moon,","the thunders groan."],"day":"06-09"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["U dvorištu ambar prazan stoji,","još se sjeća kad je bogat bio,","sva su okna bila puna žita","i miša je često pogostio."],"en":["The granary stands empty in the yard;","it still recalls when it was rich and fine,","when all its bins were brimming full of grain,","and often it would treat a mouse to dine."],"day":"06-10"},{"slug":"krava-i-koka","title_hr":"Krava i koka","title_en":"The Cow and the Hen","hr":["Kravica je naša Bjelka","cijeli dan na paši bila,","a navečer slatkog mlijeka","dječici je podarila."],"en":["Bjelka, our dear little cow,","spent the whole day in the field,","and at evening, milk so sweet","to the children she would yield."],"day":"06-11"},{"slug":"i-jos-se-pitam","title_hr":"I još se pitam","title_en":"And I Still Wonder","hr":["Kako na dnu mora","kose travu","i kako muzu","morsku kravu?"],"en":["On the deep sea floor,","how do they mow the hay?","And how do they milk","the sea cow, anyway?"],"day":"06-12"},{"slug":"plavi-se-jadran-talasa","title_hr":"Plavi se Jadran talasa","title_en":"The Blue Adriatic Sways","hr":["Tko devize sobom nosi,","Jadranom se plavim kiti,","a naš radnik u snovima,","može more samo sniti."],"en":["Those who carry foreign money","wear the blue sea like a prize;","while our worker, in his dreaming,","sees the sea with sleeping eyes."],"day":"06-13"},{"slug":"hvala-gradu-valpovu","title_hr":"Hvala gradu Valpovu","title_en":"Thank You, Town of Valpovo","hr":["„Tu mi žive predci od davnina,","u pitomom kraju meni dragom,","u ljepoti slavonskih ravnina,","u Valpovu u gradiću blagom.“"],"en":["“Here my forebears lived since days of old,","in a peaceful land so dear to me,","where the fair Slavonian plains unfold,","in Valpovo, gentle as can be.”"],"day":"06-14","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"pjesma-sinu","title_hr":"Pjesma sinu!","title_en":"A Poem for My Son!","hr":["Živio sam s tobom sretno svoju mladost.","Spavao si, sine, na mojim rukama.","U igri sa tobom dijelio sam radost.","Za bol tvoju ja sam bio na mukama."],"en":["I lived my youth with you, in happiness, my boy.","You slept, my son, so often in my arms at rest;","in playing with you, I would share in all your joy;","and when you were in pain, I suffered, sore distressed."],"day":"06-15","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"blago-meni-jer-me-majka-zeni","title_hr":"Blago meni, jer me majka ženi","title_en":"Lucky Me, My Mother's Marrying Me Off","hr":["Kao momak u Sopju sam bio,","ljepših cura, ja nisam vidio.","Preko dana žito sam vršio,","a navečer curice ljubio."],"en":["In Sopje, as a lad, I'll say outright:","no prettier girls had ever met my sight.","By day I threshed the wheat with all my might,","and kissed the little girlies every night."],"day":"06-16"},{"slug":"sokica","title_hr":"Šokica","title_en":"Šokica","hr":["Na polju je kao heroina,","kada srpom zlatno klasje žanje.","U posijelu uz kap rujnog vina,","svom je diki umiljato janje."],"en":["In the fields, a heroine so daring,","reaping golden grain, her sickle swinging;","at the sijelo, a wine-cup sharing,","to her darling, like a lamb, she's clinging."],"day":"06-17"},{"slug":"slavonija","title_hr":"Slavonija","title_en":"Slavonia","hr":["Kad navečer sunce zađe,","bezbroj zvijezda nebom sija.","Nigdje nema ljepšeg kraja","nego što je Slavonija."],"en":["When the sun has set at evening,","countless stars shine bright and fair;","there is not a land more lovely","than Slavonia, anywhere."],"day":"06-18"},{"slug":"lastina-kuca","title_hr":"Lastina kuća","title_en":"The Swallow's House","hr":["Kad prođe neko vrijeme","i stigne ljeto vruće,","ptići veselo cvrče,","jer žele van iz kuće."],"en":["When a little time has passed","and hot summer comes about,","little chicks chirp merrily,","for they're longing to get out!"],"day":"06-19"},{"slug":"zeljni-snovi","title_hr":"Željni snovi","title_en":"Dreams of Longing","hr":["Želim da mi snovi teku,","u noć tihu, toplu, meku.","Znaš li što bih htio sniti?","To da mi je s tobom biti."],"en":["How I wish my dreams took flight","through the still, warm, gentle night.","Do you know what I'd dream of?","Just to be with you, my love."],"day":"06-20"},{"slug":"slavonac-na-jadranu","title_hr":"Slavonac na Jadranu","title_en":"A Slavonian on the Adriatic","hr":["Poj sirena još odzvanja zrakom,","more šumi, vjetar ga talasa,","ljepše pjesme nisam nikad čuo,","do šuštanja zrelog žitnog klasa."],"en":["The sirens' song still echoes on the air,","the sea is stirred by wind, the waves resound;","a lovelier song I never yet have heard","than ripened wheat-ears rustling all around."],"day":"06-21"},{"slug":"procvjetala-stara-lipa","title_hr":"Procvjetala stara lipa","title_en":"The Old Linden Is in Bloom","hr":["Procvjetala stara lipa","u dvorištu naše kuće,","braco, seka, baka, deka,","brali su je, eto, jučer."],"en":["The old linden is in bloom","in the yard outside our door;","brother, sister, Gran and Grandpa","picked its flowers the day before."],"day":"06-22"},{"slug":"osvrt-kroz-sopje","title_hr":"Osvrt kroz Sopje","title_en":"A Look Around Sopje","hr":["Kada kreneš cestom Podravine","koja veže Slavonske ravnice,","tu ljepotu i gledat je milo,","eto, tu se Sopje nastanilo."],"en":["When you travel the Podravina road","that connects Slavonia's level plains,","such a beauty, lovely just to see:","look, right there is where Sopje came to be."],"day":"06-23","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"kad-ivanje-u-sopju-osvane","title_hr":"Kad Ivanje u Sopju osvane","title_en":"When St John's Day Dawns in Sopje","hr":["Bruji žica i vrisne Šokica,","preko Luke odjekne ravnica.","Ej, Sopjani, cvjetalo vam cvijeće","čekat ćemo Dravsko pramaljeće."],"en":["Strings are humming, and a Šokica cries,","over the Luka the whole plain replies.","Hey, Sopje folk, may flowers bloom each year!","We'll wait until the Drava Spring is here."],"day":"06-24","occ_hr":"Ivanje · napisano na današnji dan, 2012.","occ_en":"St John's Eve · written on this day in 2012"},{"slug":"diljem-slavonije","title_hr":"Diljem Slavonije","title_en":"All Across Slavonia","hr":["Eh što volim \"VALPOVAČKO LJETO\"!","Kad se skupi Šokadija mlada,","pa se kolo šorom zavijori,","a pod šat'rom svakojaka slada."],"en":["Eh, how I love the \"Valpovo Summer\"!","When young Šokadija gathers round,","and the kolo whirls along the lane,","and beneath the tent the treats abound."],"day":"06-25","occ_hr":"Valpovačko ljeto","occ_en":"Valpovo Summer festival"},{"slug":"dakovo-je-biser-slavonije","title_hr":"Đakovo je biser Slavonije","title_en":"Đakovo Is the Pearl of Slavonia","hr":["Ravnica te plodovima hrani,","a bregovi natapaju vinom.","Sretan onaj tko u tebi živi,","tko se može zvati tvojim sinom."],"en":["The plain feeds you with the fruit it yields,","and the hills will water you with wine;","happy he who lives within your borders,","he who can be called a son of thine."],"day":"06-26"},{"slug":"macak","title_hr":"Mačak","title_en":"The Tomcat","hr":["Eh, da mogu mačak biti,","makar i crn bio.","Rado bih se mladoj ženi,","ja u krilu svio."],"en":["Oh, if I could be a tomcat,","black, for all I care,","in a young wife's lap I'd gladly","curl up then and there."],"day":"06-27"},{"slug":"nek-se-slavi-u-sopju-veselje","title_hr":"Nek' se slavi u Sopju veselje","title_en":"Let Sopje Celebrate and Make Merry","hr":["Sopjani se sa agrarom bave,","rodne njive plodove im daju.","Svu ljepotu u svom selu slave,","zato žive u zemaljskom raju."],"en":["Sopje's people farm and till the land;","fertile fields give fruit to those who sow;","they rejoice in beauty close at hand,","so they live in paradise below."],"day":"06-28"},{"slug":"slavonija","title_hr":"Slavonija","title_en":"Slavonia","hr":["Opet tamo na istoku","srijemskom se ravnicom veže","talasasto more žita,","sve dokle ti oko seže."],"en":["There, again, toward the east,","joining Srijem's level plain,","far as ever eye can reach","rolls a billowing sea of grain."],"day":"06-29"},{"slug":"zaspalo-mace","title_hr":"Zaspalo mače","title_en":"The Sleeping Kitten","hr":["I kad spava, motor radi,","ona tiho prede.","Oh, te mačke baš ne znaju","gorivo da štede!"],"en":["Even sleeping, motor running,","purring soft and deep.","Oh, these cats just never learn","fuel isn't cheap!"],"day":"06-30"},{"slug":"domovino-moja","title_hr":"Domovino moja","title_en":"My Homeland","hr":["Slavonijo, zemljo ponosita,","malo ravna, malo bregovita,","zlatnim klasjem ti si okićena","i sa rujnim vinom zalivena."],"en":["O Slavonia, land so proud and fair,","somewhat flat, and hilly here and there,","decked in golden ears of wheat, you shine,","watered well with ruby-coloured wine."],"day":"07-01"},{"slug":"rascvjetano-ljeto","title_hr":"Rascvjetano ljeto","title_en":"Summer in Full Bloom","hr":["Ljetno sunce osušilo rosu,","što je bila trava umivena.","Nas smo dvoje sretni, zagrljeni,","igrali se na otkosu sijena."],"en":["Summer sunshine dried away the dew","that had washed the grass at break of day;","we two, happy, in each other's arms,","on the swath of new-mown hay would play."],"day":"07-02"},{"slug":"beracica-cvijeca","title_hr":"Beračica cvijeća","title_en":"The Flower Gatherer","hr":["Širio se miris pokošenog sijena,","a zeleno polje i oku je milo.","Na livadi sjedi divna, mlada žena,","bere poljsko cvijeće i skuplja u krilo."],"en":["The scent of new-mown hay was spreading on the air,","the field was green and sweet for any eye to see;","upon the meadow sat a woman, young and fair,","and picked wild flowers, gathering them on her knee."],"day":"07-03","occ_hr":"napisano na današnji dan, 1977.","occ_en":"written on this day in 1977"},{"slug":"cvrcak","title_hr":"Cvrčak","title_en":"The Cricket","hr":["Cvrčak cvrči,","violinu svira.","On ne voli","da ga netko dira.","Čim ga takneš,","prestane da svira."],"en":["Cricket chirrups,","plays his violin.","He can't bear a","finger on his skin.","Touch him, and he","stops his violin."],"day":"07-04"},{"slug":"plavi-se-jadran-talasa","title_hr":"Plavi se Jadran talasa","title_en":"The Blue Adriatic Sways","hr":["Ljetno sunce morem žeže.","Hoteli su stalno puni,","a na plaži dupe griju,","samo stranci i tajkuni."],"en":["Summer sun scorches the sea,","the hotels are full year-round,","and on beaches, warming bums,","only strangers and tycoons are found."],"day":"07-05","occ_hr":"napisano na današnji dan, 1985.","occ_en":"written on this day in 1985"},{"slug":"zora-te-meni-u-zagrljaj-vraca","title_hr":"Zora te meni u zagrljaj vraća","title_en":"Dawn Brings You Back into My Arms","hr":["Mi se gubimo u oblaku sreće,","noć mi je tada blažena i kraća,","a zlatnim zracima veselu, sretnu,","zora te meni u zagrljaj vraća."],"en":["We lose ourselves within a cloud of joy;","my night grows short then, blissful in its charms,","and, glad and happy, on its golden rays,","my love, the dawn brings you back into my arms."],"day":"07-06","occ_hr":"napisano na današnji dan, 1983.","occ_en":"written on this day in 1983"},{"slug":"ni-postaru-nije-lako","title_hr":"Ni poštaru nije lako","title_en":"It's Not Easy for the Postman Either","hr":["Ni poštaru lako nije,","dok ga žarko sunce grije.","On veliku torbu vuče","i brojeve traži kuće."],"en":["Nor is a postman's life so sweet","while he's baking in the heat;","he must lug a great big sack,","hunting house numbers, there and back."],"day":"07-07"},{"slug":"postovanom-mirku-novoselicu","title_hr":"Poštovanom Mirku Novoseliću","title_en":"To the Esteemed Mirko Novoselić","hr":["Kada budu Muze htjele,","prihvati se pera tada,","pusti maštu među zvijezde","i dobit ćeš novog rada."],"en":["When the Muses so desire,","take the pen in hand right then,","let your fancy roam the stars,","and you'll have new work again."],"day":"07-08","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"sretni-saran","title_hr":"Sretni šaran","title_en":"The Lucky Carp","hr":["Po vodi se jutros,","mali šaran šeta,","i sveg glasa pjeva,","nitko mu ne smeta."],"en":["This morning in the water","a little carp's at play;","he sings with all his voice,","with no one in his way."],"day":"07-09"},{"slug":"jos-jedan-dan","title_hr":"Još jedan dan","title_en":"One More Day","hr":["Još jedan je prošao dan,","tihi su večernji sati.","Molim te, dođi, voljena","što prije do mene svrati."],"en":["One more day has passed away,","and the evening hours are still.","Please, beloved, come to me,","come as soon as ever you will."],"day":"07-10"},{"slug":"prijatelji-slavnog-komla-grada","title_hr":"Prijatelji slavnog Komla grada","title_en":"Friends from the Famous Town of Komlo","hr":["Što je lijepo neka dugo traje,","obostrano družili se često,","svu ljepotu to druženje daje,","bilo naše ili vaše mjesto."],"en":["What's lovely, let it last for many a day;","let's often meet as friends, in your town or ours;","such friendship gives all beauty, in its way,","no matter where we spend our pleasant hours."],"day":"07-11"},{"slug":"ispod-stare-lipe","title_hr":"Ispod stare lipe","title_en":"Beneath the Old Linden","hr":["Kad bi stara lipa","ispričati znala,","sve poljupce slatke","koje si mi dala."],"en":["If the old linden","could tell, if it knew,","of all the sweet kisses","that I had from you."],"day":"07-12","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"mravinjak","title_hr":"Mravinjak","title_en":"The Anthill","hr":["Svi marljivo rade","sve do kasne noći –","čak i mali mravi","majstori su pravi.","Kada spavat pođu","- eh, kakve li sloge! -","Svi zubiće peru","i malene noge."],"en":["All of them work hard","till late in the night;","even the small ants too","are masters through and through.","When they go to bed","(how in step they go!)","they all wash their little teeth","and each tiny toe."],"day":"07-13"},{"slug":"sto-si-skrivila-generacijo","title_hr":"Što si skrivila generacijo?","title_en":"Generation, What Was Your Crime?","hr":["Radio sam četrdeset ljeta,","da postanem socijalna bijeda."],"en":["I've worked for forty summers, just to be","a welfare case, reduced to misery."],"day":"07-14"},{"slug":"ja-obicni-smrtnik","title_hr":"Ja obični smrtnik!","title_en":"I, an Ordinary Mortal!","hr":["Oh, božice moja!","Kakav sam ja drznik.","Kada te sa svetog","pijedestala skidam,","u naručje svoje.","Ja obični smrtnik."],"en":["What a daring man I am,","oh, my goddess, my immortal,","when from your holy pedestal","I lift you down this way","into my arms:","I, an ordinary mortal."],"day":"07-15","occ_hr":"napisano na današnji dan, 1983.","occ_en":"written on this day in 1983"},{"slug":"crvenkapa","title_hr":"Crvenkapa","title_en":"Little Red Riding Hood","hr":["Stazom hita Crvenkapa,","ljetno sunce šumom plovi.","Cvijeće bere, sluša ptice","i leptire male lovi."],"en":["Riding Hood runs down the pathway,","summer sun sails through the sky;","she picks flowers, hears the birdsong,","chases every butterfly."],"day":"07-16"},{"slug":"prija","title_hr":"Prija","title_en":"My Prija","hr":["Nakon druge, treće čaše,","jezici se razvezaše."],"en":["By the second glass, the third,","tongues were loosened, word by word."],"day":"07-17","occ_hr":"napisano na današnji dan, 1997.","occ_en":"written on this day in 1997"},{"slug":"sam","title_hr":"Sam!","title_en":"Alone!","hr":["Gledam zvjezdano nebo,","sam u tihoj noći.","Maštam o ljubavi našoj","i čekam kad ćeš mi doći."],"en":["I gaze at the starry sky,","alone in the quiet night.","I dream of the love we share","and wait for you to come in sight."],"day":"07-18","occ_hr":"napisano na današnji dan, 1984.","occ_en":"written on this day in 1984"},{"slug":"sismis-ili-mis","title_hr":"Šišmiš ili miš","title_en":"Flittermouse or Mouse","hr":["Bio jedan šišmiš","koji je izgubio šiš,","pa je postao miš.","Šišmiš","minus","šiš,","jednako","miš!"],"en":["Once there lived a flittermouse","who lost his flitter in the house,","and so became a mouse.","Flittermouse","minus","flitter","equals","mouse!"],"day":"07-19"},{"slug":"da-spasimo-stare-obicaje","title_hr":"Da spasimo stare običaje","title_en":"Let Us Save the Old Customs","hr":["Nekada se kosom zrelo žito želo,","sa srpom kupilo, u snoplje vezalo,","u krstine slagalo i kući vozilo,","potom vršalicom žito ovršilo."],"en":["Once, with scythes, they used to mow the ripened wheat,","gather it with sickles, bind the sheaves up neat,","stack them into shocks and cart them down the lane,","and the thresher then would thresh out all the grain."],"day":"07-20","occ_hr":"napisano na današnji dan, 2008.","occ_en":"written on this day in 2008"},{"slug":"slavonac-na-jadranu","title_hr":"Slavonac na Jadranu","title_en":"A Slavonian on the Adriatic","hr":["Skitao sam po Jadranu plavom,","od Rovinja do čuvenog Splita,","ali nigdje ja vidio nisam,","ljepšeg mora do slavonskog žita."],"en":["Along the blue Adriatic I've roamed,","from Rovinj down to famous Split, my feet","have carried me, but nowhere have I seen","a fairer sea than our Slavonian wheat."],"day":"07-21"},{"slug":"puzic-i-kucica","title_hr":"Pužić i kućica","title_en":"The Little Snail and His House","hr":["Odgovara pužić:","\"Meni teška nije,","ljeti imam hlada,","a zimi me grije.\"","Pitale ga gliste","što se tako vuče:","\"Mogu kako hoću,","kod svoje sam kuće!\""],"en":["The little snail replies:","\"It's not heavy for me:","in summer I have shade,","in winter, warm I'll be.\"","The earthworms asked him why","he dragged along so slow:","\"I do just as I please,","I'm home wherever I go!\""],"day":"07-22"},{"slug":"vatre-na-konjari","title_hr":"Vatre na konjari","title_en":"Bonfires on the Konjara","hr":["Nekada davno u ono staro doba,","dok su konji bili prvoklasna roba.","Svaku noć bi konje napasali ljudi,","U zvjezdanoj noći, dok mjesec zarudi."],"en":["Long, long ago, back in the days of old,","when horses were first-class goods, bought and sold,","each night the people grazed their horses, led","out under stars, as the moon rose, glowing red."],"day":"07-23","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"zov-domovine","title_hr":"Zov domovine","title_en":"The Call of the Homeland","hr":["Zato svoju zemlju i ljubi i voli,","najdražom je zovi, vrijeđat ne dozvoli.","Ona ti sve prašta, k'o rođena mati.","Tu rođenu grudu treba čuvat znati."],"en":["So love your land, and cherish her, and hold her dear;","call her the dearest one, let no insult come near.","She forgives all, just like the mother of your birth;","you must know how to keep and guard your native earth."],"day":"07-24"},{"slug":"hodi-mjesece-zvijezdama","title_hr":"Hodi, mjeseče, zvijezdama","title_en":"Walk, O Moon, Among the Stars","hr":["Molim te, mjeseče sjajni,","ne svijetli ove noći,","kad poljubim dragu moju,","ti možeš opet doći."],"en":["Shining moon, I beg you, please,","do not shine for us tonight;","when I've kissed my darling, then","you may come back into sight."],"day":"07-25","occ_hr":"napisano na današnji dan, 1989.","occ_en":"written on this day in 1989"},{"slug":"dva-bureta-prodajem-za-vino","title_hr":"Dva bureta prodajem za vino","title_en":"Two Wine Barrels for Sale","hr":["Kad u jesen napunim bačvicu,","svakog dana uzimam litricu.","Godinama ja već tako radim,","pijem vino, pomalo se sladim."],"en":["When in the autumn I have filled the cask,","a litre every day is all I ask.","For years and years I've done it just this way:","I drink my wine and savour it each day."],"day":"07-26","occ_hr":"napisano na današnji dan, 2001.","occ_en":"written on this day in 2001"},{"slug":"dobro-dosli-prijatelji-dragi","title_hr":"Dobro došli prijatelji dragi!","title_en":"Welcome, My Dear Friends!","hr":["To je bilo trideset i treće,","u mjesecu kad se žito želo,","dvajs'devetog, a bio je petak,","pa sam svakoj radosti početak."],"en":["It was in the year of thirty-three,","in the month when they were reaping wheat,","the twenty-ninth, and Friday was the day,","so every joy begins with me, I say."],"day":"07-27","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"na-dan-vjencanja","title_hr":"Na dan vjenčanja!","title_en":"On Your Wedding Day!","hr":["U ovome času ti ćeš gnijezdo sviti.","Uskoro ćeš i ti svoje čedo zvati.","Voli svoje bližnje i voljen ćeš biti.","To ti želi: sestra, tvoj otac i mati."],"en":["In this very hour you will build your own nest;","soon you'll call a child your own, a daughter or a son.","Love those close to you, and you'll be loved and blessed.","So wish your sister, father, mother, all as one."],"day":"07-28","occ_hr":"napisano na današnji dan, 1979.","occ_en":"written on this day in 1979"},{"slug":"poezijski-rad-kroz-zivot","title_hr":"Poezijski rad kroz život","title_en":"A Life's Work in Poetry","hr":["Ivan Benak mi je ime,","pjesnik koji piše rime.","Još od mojih školskih dana,","poezija mi je hrana.","","Šezdeset je ljeta prošlo,","od kada sam napisao:","„NE BUDI ME, MAJKO, RANO,","JOŠ SE NISAM NASPAVAO“.","","I starački došli dani,","nema zdravlja kao prije,","ali srce moje gordo,","ukrotila starost nije.","","I još nešto važno ima,","reći ću vam sada svima.","Od preksutra svako veče',","SEDAMDESET OSMA TEČE!"],"en":["Ivan Benak is my name,","poet: rhyming is my aim.","Since my days at school began,","poetry has fed this man.","","Sixty summers now have passed","since I wrote, so long ago:","\"MOTHER, DO NOT WAKE ME EARLY,","I AM NOT YET RESTED, NO.\"","","Now the days of age are here,","and my health is not the same,","yet my heart, as proud as ever,","age has never learned to tame.","","Something else important, too,","I will now tell all of you:","two days hence, as night draws near,","starts my SEVENTY-EIGHTH YEAR!"],"day":"07-29","special":"birthday","sig_hr":"Valpovo, 18. 07. 2010.","sig_en":"Valpovo, July 18, 2010","occ_hr":"Pjesnikov rođendan (1933.)","occ_en":"The poet's birthday (1933)"},{"slug":"dobro-dosli-prijatelji-dragi","title_hr":"Dobro došli prijatelji dragi!","title_en":"Welcome, My Dear Friends!","hr":["U Belišću pedeset i prve,","dva pupoljka bila su na radu.","Jednog dana tu se upoznali,","jedno drugom svoje srce dali."],"en":["In Belišće, in nineteen fifty-one,","two young buds were working side by side.","There one day they met, and from the start","each one gave the other one their heart."],"day":"07-30"},{"slug":"ne-sudi","title_hr":"Ne sudi","title_en":"Don't Judge","hr":["Tijelo mi je grubo,","gipko kao Drava,","jer ja sam rođen","u znaku lava."],"en":["My body is rough,","yet lithe as the Drava's line,","for I was born","beneath the Lion's sign."],"day":"07-31"},{"slug":"suncokret-i-mak","title_hr":"Suncokret i mak","title_en":"The Sunflower and the Poppy","hr":["Na vrhu mu žuto tjeme,","u glavi mu silno sjeme,","klonu glava, teška, žuta,","pade sjeme pokraj puta.","Misli tužno suncokret:","oh, što nisam crven cvijet?"],"en":["At the top, his yellow crest,","in his head, the seeds close-pressed;","heavy, yellow, droops his head,","by the roadside seed is shed.","Sadly the sunflower sighs:","\"Why am I not red?\" he cries."],"day":"08-01"},{"slug":"anice","title_hr":"Anice","title_en":"To Anica","hr":["Svakog dana kad zora zarudi,","sretnu, vedru, nek' te sunce budi."],"en":["Each day, as dawn first reddens into light,","may the sun wake you, cheerful, glad and bright."],"day":"08-02"},{"slug":"poezija-na-trznici","title_hr":"Poezija na tržnici","title_en":"Poetry at the Market","hr":["Kolovozom svakog ljeta,","pjesnici se gordo roje,","u Đakovu, na tržnici,","čitajući pjesme svoje."],"en":["In the August of each year","poets proudly swarm along","in Đakovo, at the market,","each one reading out his song."],"day":"08-03","occ_hr":"napisano na današnji dan, 2009.","occ_en":"written on this day in 2009"},{"slug":"etno-kuca-semialjac-kate","title_hr":"Etno kuća Semialjac Kate","title_en":"Kata Semialjac's Ethno House","hr":["Štala prazna, nema više konja,","plug drveni i ornice stoje,","vjetrenjača u štaglju miruje,","vremena su učinila svoje."],"en":["The stable's empty, there's no horse at all,","the wooden plough and ploughing gear stand still,","the winnowing machine rests in the barn:","the times have done their work, as all times will."],"day":"08-04"},{"slug":"rodena-gruda","title_hr":"Rođena gruda","title_en":"Native Soil","hr":["Najljepše je uvijek na rođenoj grudi","i zemljica ova što te kruhom hrani.","Tu si se rodio, tu živi i budi.","Ne daj domovinu, s ljubavlju je brani."],"en":["It's always loveliest within your native land,","and this dear little earth that gives you bread each day.","Here you were born; so live here, here take up your stand.","Don't give your homeland up; with love, keep foes away."],"day":"08-05","occ_hr":"Dan pobjede i domovinske zahvalnosti","occ_en":"Victory and Homeland Thanksgiving Day"},{"slug":"unuci-andreji-portret","title_hr":"Unuci Andreji","title_en":"To My Granddaughter Andreja","hr":["Imam jednu unuku malu,","uvijek je spremna za svaku šalu.","Ne ide u školu, al' slike riše,","poneko slovo već zna da piše.","Vrlo je vrijedna, voli da radi,","voli da gricka i da se sladi.","Svu hranu voli rado da jede,","to je od svoga vidjela djede."],"en":["I've got a granddaughter who's still very small;","she's always up for a joke, any at all.","She's not yet in school, but she draws with a will;","a few of her letters she writes with some skill.","She's very hard-working, she likes to do chores,","she likes to nibble, and sweets she adores.","She eats any food, and she finds it all good:","she's watched her own grandpa, and does as he would!"],"day":"08-06"},{"slug":"lastina-kuca","title_hr":"Lastina kuća","title_en":"The Swallow's House","hr":["Maleni brzo rastu,","dođe i konac ljeta.","U jata se tada skupe –","odoše na kraj svijeta!"],"en":["Quickly grow the little ones,","and the summer's end draws nigh;","then they gather into flocks,","off to the world's end they fly!"],"day":"08-07"},{"slug":"hrabra-budi","title_hr":"Hrabra budi","title_en":"Be Brave","hr":["Kada mora iz snova te budi,","kada tuga razara ti grudi,","kada netko zbog ljubavi sudi,","ti ne plači, nego hrabra budi."],"en":["When a nightmare wakes you from your rest,","when your sorrow tears apart your breast,","when someone condemns the love you've confessed,","do not cry: be brave, and stand the test."],"day":"08-08","occ_hr":"napisano na današnji dan, 1987.","occ_en":"written on this day in 1987"},{"slug":"ugodno-druzenje-umirovljenika","title_hr":"Ugodno druženje umirovljenika","title_en":"A Pleasant Pensioners' Get-Together","hr":["Veselo je, hvala dragom Bogu,","zaigraše kolo, tango, polku,","nek se vidi što PENZIĆI mogu,","sutra ćemo misliti na boljku."],"en":["It's merry, thanks be to the Lord above;","they danced the kolo, tango, polka too;","let all now see what OLDIES are made of:","tomorrow we'll give aches a thought or two."],"day":"08-09"},{"slug":"hvaljen-isus-majko-nasa","title_hr":"Hvaljen Isus, Majko naša","title_en":"Praised Be Jesus, Our Mother","hr":["Mnogi ljudi na svetištu,","svetoj Gospi zavjet daju.","Da l' zbog bola ili jada,","kakav problem već imaju."],"en":["Many people at the shrine there","to Our Lady make a vow,","be it out of pain or sorrow","or whatever grieves them now."],"day":"08-10","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"lovacke-price","title_hr":"Lovačke priče","title_en":"Hunters' Tales","hr":["Jednom se ribiču,","zvanom brza ruka,","u šumi na panju","uhvatila štuka."],"en":["Once a fisherman","whom they called Quick Hand,","on a stump in the woods","caught a pike, on dry land!"],"day":"08-11"},{"slug":"opijelo-ljubavi","title_hr":"Opijelo ljubavi","title_en":"Requiem for Love","hr":["Zašto uvijek pišem na kraju života?","A preskačem sreću onih prvih dana,","dok još srce nije bilo puno rana?"],"en":["Why do I always write when life is at its end,","and skip the joy of those first days, right at the start,","when there were not yet many wounds upon my heart?"],"day":"08-12"},{"slug":"umirovljenicki-jadi","title_hr":"Umirovljenički jadi","title_en":"A Pensioner's Woes","hr":["Kad pogledam što u kasi osta,","taman, brale, za rakiju dosta.","Da popijem i ublažim tugu","čekajući crkavicu drugu."],"en":["And when I see what's left inside my till,","there's just enough, old mate, for rakija still,","to drink it down and ease my grief a bit,","and wait for the next pittance after it."],"day":"08-13"},{"slug":"zora-te-meni-u-zagrljaj-vraca","title_hr":"Zora te meni u zagrljaj vraća","title_en":"Dawn Brings You Back into My Arms","hr":["U mislima s tobom, zorom se budim,","kada se zlatno sunašce rađa.","U grudima, draga, svuda te nosim.","Od ljubavnog žara postaješ mlađa."],"en":["With you in thought, I waken with the dawn,","just as the little golden sun is born;","wherever I may go, you're in my breast,","love's ardour makes you younger every morn."],"day":"08-14"},{"slug":"bol-kroz-zivot","title_hr":"Bol kroz život","title_en":"A Lifetime of Pain","hr":["Ponekad se teško hodi,","neravni su često puti,","kroz život me sudba vodi.","Ti uz mene, Gospo, budi!"],"en":["Sometimes it is hard to tread,","often rugged is the way;","through my life by fate I'm led:","Lady, stay by me, I pray!"],"day":"08-15","occ_hr":"Velika Gospa","occ_en":"Assumption Day"},{"slug":"prica-o-muji-i-fati","title_hr":"Priča o Muji i Fati","title_en":"The Tale of Mujo and Fata","hr":["Al' samoća dušu truje,","mladost traži želje svoje,","a noći su puste, duge,","ljepši život je u dvoje."],"en":["Loneliness, though, poisons souls,","youth has longings of its own,","and the nights are long and empty:","life is sweeter not alone."],"day":"08-16","occ_hr":"napisano na današnji dan, 2004. (inačica „Storija o Mati i Kati“)","occ_en":"written on this day in 2004 (the version “The Story of Mata and Kata”)"},{"slug":"izgubljena-cipelica","title_hr":"Izgubljena cipelica","title_en":"The Lost Shoe","hr":["Izgubih svoju","cipelu desnu,","ali ja ne znam","s noge koje.","Molim nalaznika","da sam provjeri,","jer stonoge svoje","noge ne broje."],"en":["I've gone and lost","my right-hand shoe,","but I can't say","which foot it's from.","I ask the finder","to check it himself:","do centipedes ever","count their feet? No, never!"],"day":"08-17"},{"slug":"pjesma-valpovu","title_hr":"Pjesma Valpovu","title_en":"A Poem for Valpovo","hr":["Kad u parku ptice zapjevaju,","nigdje nema tako lijepog kraja.","Rodne njive plodove nam daju,","to je dio zemaljskoga raja."],"en":["When the birds in the park begin to sing,","there's no lovelier land beneath the skies;","fertile fields their fruit to us will bring:","this is part of earthly paradise."],"day":"08-18"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["Pod orahom djeda kosu kuje,","baka užad plete pokraj kuće.","Miris kruha dvorištem se širi,","bit će danas i pogače vruće."],"en":["Beneath the walnut Grandpa peens his scythe,","and Grandma plaits her ropes beside the wall;","the smell of bread is spreading through the yard,","today there'll be hot flatbread for us all."],"day":"08-19","occ_hr":"napisano na današnji dan, 2006.","occ_en":"written on this day in 2006"},{"slug":"ljubav-se-ne-mjeri","title_hr":"Ljubav se ne mjeri","title_en":"Love Is Not Measured","hr":["Nikad neću žalit' što sam te ljubio.","Za tvoju sam ljubav tebi svoju dao.","Da se opet rodim, opet bih tvoj bio","i na grudi tvoje sav sretan bih pao."],"en":["I'll never feel regret that I have loved you so;","for all your love I gave you mine, I gave it all;","and were I born again, I'd still be yours, I know,","upon your breast, in perfect happiness, I'd fall."],"day":"08-20"},{"slug":"uspavanka","title_hr":"Uspavanka","title_en":"Lullaby","hr":["Lubenice slatke","i dinje žute,","ako ih nećeš,","one se ljute."],"en":["Sweet watermelons,","melons of gold:","if you refuse them,","they grumble and scold."],"day":"08-21"},{"slug":"haiku","title_hr":"Haiku","title_en":"Haiku","hr":["SVITANJE:","Mjesec se gasi,","pijetao kljuca zoru,","miriše jutro."],"en":["Dawn:","The moon is fading,","a rooster pecks at the dawn,","the morning's fragrant."],"day":"08-22"},{"slug":"lijepo-je-biti-voljen","title_hr":"Lijepo je biti voljen","title_en":"It's Lovely to Be Loved","hr":["Željno čekam trenutak,","kada ću s tobom biti.","U naručju tvome, draga,","ljubavne snove sniti."],"en":["Eagerly I wait the moment","when I'll be with you, my dear,","in your arms, my darling, dreaming","dreams of love, and hold you near."],"day":"08-23","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"kad-tambura-srce-dira","title_hr":"Kad tambura srce dira","title_en":"When the Tambura Touches the Heart","hr":["Sviraj samo, prijatelju,","novu glazbu svakog dana,","pa će tvojim časnim radom,","Valpovština biti znana!"],"en":["Just keep playing, my good friend,","some new music every day,","so your honest work will make","Valpovština known far away!"],"day":"08-24","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"skromnost","title_hr":"Skromnost!","title_en":"Modesty!","hr":["Ja ne želim biti,","ni heroj u boju,","već želim tebe","i ljubav tvoju."],"en":["I don't wish to be","a hero in the war;","I want only you","and your love, nothing more."],"day":"08-25"},{"slug":"suha-kora-prove","title_hr":"Suha kora prove","title_en":"The Dry Crust of Cornbread","hr":["U snovima bijelog kruha,","svježu krišku ja sam snio,","a na javi koru prove","suzama sam natopio."],"en":["In my dreams I used to dream","of a fresh white slice of bread,","but awake, the cornbread crust","I would soak with tears instead."],"day":"08-26"},{"slug":"kako-nosorog-brise-nos","title_hr":"Kako nosorog briše nos","title_en":"How the Rhino Wipes His Nose","hr":["Kako nosorog","briše nos","kada na njemu","ima rog?"],"en":["How does a rhino","wipe his nose","when on top of it","a horn grows?"],"day":"08-27"},{"slug":"nard-je-selo-sto-ga-ljubi-drava","title_hr":"Nard je selo što ga ljubi Drava","title_en":"Nard Is the Village the Drava Kisses","hr":["Na tamburi kada cikne žica,","odjekuje Slavonska ravnica."],"en":["When the tambura string rings sharp and high,","Slavonia's plain resounds in reply."],"day":"08-28"},{"slug":"podravino-diko-moja","title_hr":"Podravino, diko moja","title_en":"Podravina, My Pride","hr":["Ja u Sopju nikog nemam,","al' me srce k njemu vuče.","Ostalo mi tu djetinjstvo","u sjećanju stare kuće."],"en":["I have no one now in Sopje,","yet it draws my heart anew;","there my childhood stayed behind,","in the old house that I knew."],"day":"08-29","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"volim-ljubav","title_hr":"Volim ljubav","title_en":"I Love Love","hr":["Mladost bješe kratka","na ovome svijetu.","Zato ljubljah žene","u najljepšem cvijetu."],"en":["Youth upon this earth","lasted but an hour;","so I kissed the women","in their fairest flower."],"day":"08-30"},{"slug":"dragi-prijatelji","title_hr":"Dragi prijatelji!","title_en":"Dear Friends!","hr":["Želim da kroz knjigu ovu,","naše prijateljstvo traje,","jer stihovi ove knjige","daju nježne osjećaje."],"en":["It's my wish that through this book","our friendship will last and stay,","for the verses that it holds","tender feelings bring your way."],"day":"08-31"},{"slug":"tatina-lutkica","title_hr":"Tatina lutkica","title_en":"Daddy's Little Doll","hr":["Imam jednu lutkicu,","jedno malo đače,","pa od škole do kuće","cupka kao pače."],"en":["I have a little dolly,","a little schoolgirl, who","comes hopping home from school","the way that ducklings do."],"day":"09-01"},{"slug":"dobio-sam-pjesmu-od-marice","title_hr":"Dobio sam pjesmu od Marice","title_en":"I've Had a Poem from Marica","hr":["Poznato je, žene puno rade,","u proljeće razno bilje sade.","Dođe jesen, priroda se zlati,","žena opet za zimnicu radi."],"en":["It's known to all that women work a lot:","in spring they plant all kinds in every plot.","Then autumn comes, and nature turns to gold,","and wives put up their stores against the cold."],"day":"09-02"},{"slug":"cuvarima-noci","title_hr":"Čuvarima noći","title_en":"To the Guardians of the Night","hr":["Ništa ljepše od tambure nema,","pogotovo kad se svadba sprema."],"en":["There's nothing lovelier than the tambura's play,","especially when a wedding's on the way."],"day":"09-03"},{"slug":"zeni-za-rodendan","title_hr":"Ženi za rođendan","title_en":"To My Wife on Her Birthday","hr":["Na tom putu što me pratiš,","od svega ti srca hvala!","A dvoje si divne djece,","meni, dušo, darovala."],"en":["For the road you've walked beside me,","all my heartfelt thanks are due!","And two lovely children, darling,","were the gift I had from you."],"day":"09-04","occ_hr":"Rođendan supruge Jelke","occ_en":"His wife Jelka's birthday"},{"slug":"skolska-torba","title_hr":"Školska torba","title_en":"The School Bag","hr":["Nije teška, vjerujte,","svi je đaci nose,","a znanja je prepuna","kao cvijeće rose."],"en":["It's not heavy, honestly,","every pupil bears it too,","and it's brimming full of knowledge","like the flowers full of dew."],"day":"09-05","occ_hr":"Početak škole","occ_en":"First day of school"},{"slug":"nek-se-slavi-u-sopju-veselje","title_hr":"Nek' se slavi u Sopju veselje","title_en":"Let Sopje Celebrate and Make Merry","hr":["Sve dok bude bilo Slavonije,","skupljat će se Šokadija naša","i veselja bit će kao prije,","uz tambure dobrih tamburaša."],"en":["For as long as Slavonia stays,","our Šokadija will gather still,","there'll be merriment as in old days,","with tamburas played by men of skill."],"day":"09-06","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"buduci-nogometas","title_hr":"Budući nogometaš","title_en":"The Future Footballer","hr":["Ja unuka imam,","dobar je u školi,","al' najviše ipak,","on nogomet voli."],"en":["I have got a grandson","who does well at school,","but above all, football","is his golden rule."],"day":"09-07"},{"slug":"destinacije-opcine-sopja","title_hr":"Destinacije općine Sopja","title_en":"Destinations of Sopje Municipality","hr":["Ritska Ada tu je nekad bila,","pjesnika je ona iznjedrila.","Još je ovdje, samo što se skriva,","pjesnikovo još djetinjstvo sniva."],"en":["Here, long ago, was Ritska Ada's place;","it brought the poet forth from its embrace.","It is still here, only hidden away,","and the poet's childhood dreams there to this day."],"day":"09-08","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"andreji-za-22-rodendan","title_hr":"Andreji za 22. rođendan","title_en":"To Andreja on Her 22nd Birthday","hr":["Andrejice unučice,","draga naša golubice.","I još jedno ljeto prođe,","tvoj rođendan dragi dođe."],"en":["Andreja, our grandchild dear,","our sweet dove, whom we hold near,","one more summer's slipped away,","your dear birthday's here today."],"day":"09-09","occ_hr":"Rođendan unuke Andreje","occ_en":"His granddaughter Andreja's birthday"},{"slug":"godine-po-zelji","title_hr":"Godine po želji","title_en":"Years to Order","hr":["Kao u stara dobra vremena,","dok je još Bog hodao po zemlji.","Sa Olimpa Eros dobrostivo veli:","Zbor penzioneri, mladost se dijeli.","Koliko tko godina sada želi?"],"en":["Just as in the good old times, the days of yore,","when the Lord still walked about upon the earth,","from Olympus, Eros kindly had his say:","\"Pensioners, fall in! Youth's being given away!","How many years does each one want today?\""],"day":"09-10"},{"slug":"neposlusni-vrabac","title_hr":"Neposlušni vrabac","title_en":"The Disobedient Sparrow","hr":["Neka vam ovo, djeco,","bude savjet mali:","Uvijek slušajte starije,","da biste što više znali!"],"en":["Children, let this story be","a small word to help you grow:","always listen to your elders,","and learn all there is to know!"],"day":"09-11"},{"slug":"kritika","title_hr":"Kritika","title_en":"Criticism","hr":["Jednog dana mi reče,","kritičar strog i ljut,","da pjesme ne pišem više,","da pero bacim u kut.","Meni kad želje se jave,","k'o jesenje guste kiše,","u ruci pero se nađe","i samo pjesme piše."],"en":["One day a critic told me,","with a stern and angry look,","that I should write poems no more","and throw my pen in a nook.","But when my longings gather","like autumn's heavy rain,","a pen turns up in my hand","and just writes poems again."],"day":"09-12"},{"slug":"lastavica","title_hr":"Lastavica","title_en":"The Swallow","hr":["Kada dođe jesen,","srce me zazebe.","S odlaskom svojim","stvaraš meni sjetu.","Išao bih s tobom","u tople krajeve,","ali krila nemam","da letim po svijetu."],"en":["When the autumn comes,","my heart starts to freeze;","as you fly away,","you leave me sad and blue.","I'd go with you, swallow,","to warm lands overseas,","but I have no wings","to fly the whole world through."],"day":"09-13"},{"slug":"jos-postoji-nada","title_hr":"Još postoji nada","title_en":"There Is Still Hope","hr":["Još postoji nada","da mi snove budiš,","još postoji nada","da mi ljubav vratiš,","još postoji nada","da me nježno ljubiš.","U ljubavi našoj,","da me vjerno pratiš."],"en":["There's hope for us yet","my dreams you'll renew,","there's hope for us yet","you'll love me once more,","there's hope for us yet","you'll kiss me, soft and true,","and, side by side in love,","stay faithful as before."],"day":"09-14","occ_hr":"napisano na današnji dan, 1982.","occ_en":"written on this day in 1982"},{"slug":"dolazak-zime","title_hr":"Dolazak zime","title_en":"The Coming of Winter","hr":["Berači zrele plodove beru","i poljem pjevaju glasno.","Uskoro, djeco, doći će zima,","to nam je sada jasno."],"en":["The pickers gather in the ripened fruit","and sing across the fields, loud and clear.","Soon, children, winter will be on its way:","we all can see that it is near."],"day":"09-15"},{"slug":"radio-burza-pjesma","title_hr":"Radio burza","title_en":"Radio Burza","hr":["Dok jutarnju svoju kavu pijem,","slušam burzu, pa se i nasmijem.","To je program što se rado sluša,","svega ima što ti želi duša."],"en":["While sipping at my morning coffee cup,","I hear the Burza, and it cheers me up.","It is a programme people gladly heed;","it offers all that any soul could need."],"day":"09-16","occ_hr":"napisano na današnji dan, 2000.","occ_en":"written on this day in 2000"},{"slug":"skolska-torba","title_hr":"Školska torba","title_en":"The School Bag","hr":["S odličnim bi uspjehom","prošla škola svaka,","kad bi torba odgovor","dala mjesto đaka."],"en":["Every school would pass with honours,","every single one,","if the school bag gave the answers","and the pupils none."],"day":"09-17"},{"slug":"sopju-s-ljubavlju","title_hr":"Sopju s ljubavlju","title_en":"To Sopje, With Love","hr":["Podravino, mili zavičaju,","selo Sopje u tebi se svilo.","Nema ljepšeg od tvojega kraja,","uvijek mi je tu najbolje bilo."],"en":["Podravina, my dear native land,","Sopje village nestles in your breast;","nothing's lovelier than your countryside,","here is where I've always felt the best."],"day":"09-18","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"0-5-promila","title_hr":"0.5 promila","title_en":"0.5 Per Mille","hr":["Ujesen se svadbe prave","uz obilje rujnog vina.","Svaki otac raduje se,","kada ženi svoga sina."],"en":["Autumn's when the weddings come,","with red wine for everyone;","every father's heart is glad","when he marries off his son."],"day":"09-19"},{"slug":"imam-jedno-djevojce","title_hr":"Imam jedno djevojče","title_en":"I Have a Little Sweetheart","hr":["Imam jedno djevojče,","milo kao san.","Ja je mazim, milujem,","ljubim svaki dan."],"en":["I have a little sweetheart,","dear as a dream, I say;","I pet her and caress her","and kiss her every day."],"day":"09-20","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"sretan-ti-rodendan-denise","title_hr":"Sretan ti rođendan Denise","title_en":"Happy Birthday, Denis","hr":["Dajemo ti dara","ovo malo para,","to ti daje djeda","i voljena baka,","da bi među nama","bila ljubav jaka."],"en":["We give you a gift, dear:","a little cash here;","it comes from your Grandpa","and dear Grandma too,","so that between us","love grows strong and true."],"day":"09-21","occ_hr":"Rođendan unuka Denisa","occ_en":"His grandson Denis's birthday"},{"slug":"sjecanje-na-djetinjstvo","title_hr":"Sjećanje na djetinjstvo","title_en":"Remembering My Childhood","hr":["Djetinjstvo moje bolno mi prisjelo.","Svakoga sam dana bos po trnju hodo.","Na meni je bilo skrpljeno odijelo,","dok sam tuđe krave po strnjaku vodo."],"en":["My childhood weighs on me, a bitter pain I've known:","barefoot I walked on thorns, and did so every day;","the clothes upon my back were patched and roughly sewn,","while I led other people's cows where stubble lay."],"day":"09-22"},{"slug":"hvala-ti-draga","title_hr":"Hvala ti, draga!","title_en":"Thank You, Darling!","hr":["Još su oči tvoje, mila, pune čežnje,","a riječi su tople, iskrene i nježne.","Oh, ljubavi moja, na svemu ti hvala."],"en":["Still full of longing are those eyes of yours, my dear,","and all your words are warm and tender and sincere.","Oh, love of mine, for everything I give you thanks."],"day":"09-23","occ_hr":"napisano na današnji dan, 1973.","occ_en":"written on this day in 1973"},{"slug":"dobio-sam-pjesmu-od-marice","title_hr":"Dobio sam pjesmu od Marice","title_en":"I've Had a Poem from Marica","hr":["Eto i ja u radu sam bio,","u Baziju šljive sam kupio","i sad gledam kako šljive zriju,","čekam vrijeme da pečem rakiju."],"en":["I too have been at work in my own way:","in Bazije I bought some plums one day,","and now I watch the plums grow ripe, until","it's time to make rakija in the still."],"day":"09-24"},{"slug":"radosno-djetinjstvo","title_hr":"Radosno djetinjstvo","title_en":"Happy Childhood","hr":["Igraju se i pjevaju,","tu na djecu tete paze,","djeci pjesme tu čitaju","i tete ih divno maze.","U igri im nema kraja,","to je dio pravog raja."],"en":["Here they play and here they sing,","and the aunties mind them there;","read them rhymes of everything,","and they cuddle them with care.","There's no end to all their play,","it's a piece of heaven, I'd say."],"day":"09-25"},{"slug":"oj-oraje-oraje","title_hr":"Oj, oraje, oraje","title_en":"Oh, Walnut, Walnut Tree","hr":["Orah dobro rodi","ima jezgru pravu,","ali baba veli:","ne za sijedu glavu."],"en":["The walnut bears well,","with kernels just right,","but granny just says:","\"Not for heads gone white.\""],"day":"09-26"},{"slug":"sumski-kralj","title_hr":"Šumski kralj","title_en":"The Forest King","hr":["Što je to:","u šumi živi","šumski kralj,","ima djece milijun,","sva mu djeca","kapu nose,","a samo je","nema on."],"en":["What is this:","in the woods there lives","the forest king,","with a million young about;","all his children","wear a cap,","only he","goes without."],"day":"09-27"},{"slug":"stiglo-nam-i-vincekovo","title_hr":"Stiglo nam i Vincekovo","title_en":"Now St Vincent's Day Has Come","hr":["I to vinsko trebat će nam blago,","kad ostvare mladi svoje snove.","Dođe jesen i vino poteče,","slavit ćemo veselo svatove."],"en":["And we'll need that wealth of wine, that treasure,","when the young ones make their dreams come true.","Autumn comes, and wine begins to flow:","gladly we will feast the wedding through."],"day":"09-28"},{"slug":"dolazak-zime","title_hr":"Dolazak zime","title_en":"The Coming of Winter","hr":["Jesenje kiše tjeraju ljeto,","lišće polako žuti.","Po cesti vjetar prašinu diže","i huči – valjda se ljuti."],"en":["The autumn rains are driving summer out,","the leaves turn slowly yellow;","along the road the wind whips up the dust","and howls: perhaps he's cross, the fellow."],"day":"09-29","occ_hr":"Miholje","occ_en":"Michaelmas"},{"slug":"gusjenica","title_hr":"Gusjenica","title_en":"The Caterpillar","hr":["Ja sam mala","gusjenica.","Jedem lišće,","istina je cijela,","no, list knjige","đaka Marka","nikad nisam jela."],"en":["I'm a little","caterpillar.","I eat leaves,","every word is true,","but the leaf of","schoolboy Marko's","book I never chew."],"day":"09-30"},{"slug":"draga-nasa-unucice","title_hr":"Draga naša unučice!","title_en":"Our Dear Little Granddaughter!","hr":["Draga naša unučice!","Sve najbolje što sad znamo,","rođendan ti čestitamo!","Pa makar si sada snaša,","unuka si ipak naša."],"en":["Our dear little granddaughter!","All the best that we can say:","happy birthday to you today!","Even though you're now a wife,","you're our granddaughter for life."],"day":"10-01","occ_hr":"Rođendan unuke Željke","occ_en":"His granddaughter Željka's birthday"},{"slug":"da-spasimo-stare-obicaje","title_hr":"Da spasimo stare običaje","title_en":"Let Us Save the Old Customs","hr":["Ujesen bi ljudi kukuruze brali,","uz vino i pjesmu doma komušali.","Skupila se moba, veseli su bili,","a dečki bi cure doma otpratili."],"en":["In the autumn they would pick the maize and bring","all the cobs back home to husk, with wine, and sing.","A moba would gather, merry, every one,","and the lads would walk the girls home when all was done."],"day":"10-02"},{"slug":"zena","title_hr":"Žena","title_en":"Woman","hr":["Žena je nježno ljubila,","Mnoge je bogove rodila.","Zvijezde trepere","U njenoj kosi,","U bujnim njedrima","Mjesec skriva.","Na krhkim plećima","Planetu nosi.","I bit će voljena","Sve dok je živa."],"en":["Woman's love was tender, mild;","many a god has been her child.","Stars are twinkling","in her hair,","in her full bosom's fold","she hides the moon from view.","Her fragile shoulders hold","the planet in her care.","And loved she'll be","her whole life through."],"day":"10-03"},{"slug":"pjesnicka-zadovoljstva","title_hr":"Pjesnička zadovoljstva","title_en":"The Poets' Pleasures","hr":["Sa svih strana dične Slavonije,","svojoj duši pjesnik maštu dade:","O ljepoti, o bolu, o ratu,","netko ljubav, netko svoje jade."],"en":["From every side of proud Slavonia","the poet let his soul's own fancy flow:","of beauty, and of pain, and of the war,","one wrote of love, and one his grief and woe."],"day":"10-04"},{"slug":"sto-je-najbrze","title_hr":"Što je najbrže","title_en":"What Is Fastest?","hr":["\"Najbrže su, djeco, misli,","one se baš svega sjete.\"","Mudro reče nastavnica:","\"Misli među zvijezde lete.\""],"en":["\"Fastest, children, are our thoughts,","they can think of anything,\"","wisely then the teacher said.","\"Up among the stars they wing.\""],"day":"10-05","occ_hr":"Dan učitelja","occ_en":"Teachers' Day"},{"slug":"sokica","title_hr":"Šokica","title_en":"Šokica","hr":["Ej Šokice, milo moje janje,","na jesen te vodim na vjenčanje."],"en":["Hey, Šokica, my sweet lamb, I'm bringing","you to wed when autumn bells are ringing!"],"day":"10-06"},{"slug":"zelim-da-se-moj-glas-cuje","title_hr":"Želim da se moj glas čuje","title_en":"I Want My Voice to Be Heard","hr":["U veselju toga skupa,","i dok glazba tiho svira,","sretna djeca s balonima","poruku su slali mira."],"en":["In the gladness of that meeting,","while the music played so soft,","happy children with balloons","sent a message of peace aloft."],"day":"10-07"},{"slug":"sva-godisnja-doba","title_hr":"Sva godišnja doba","title_en":"All the Seasons","hr":["Ali nakon sreće i bol mora doći.","U moj život tiho jesen se uvukla.","Ovi tmurni dani nikad neće proći.","Kao list sa stabla srce mi je svukla."],"en":["But after happiness, pain too must have its day;","and into my life, so quietly, the autumn crept.","These gloomy days of mine will never pass away;","it stripped my heart, as from a tree a leaf is swept."],"day":"10-08"},{"slug":"blago-meni-jer-me-majka-zeni","title_hr":"Blago meni, jer me majka ženi","title_en":"Lucky Me, My Mother's Marrying Me Off","hr":["Jednog dana, majka veli meni:","„Dragi, sine, hajde se oženi!","Stigla jesen, uskoro će zima,","a u Sopju lijepih cura ima.“"],"en":["One day my mother said to me: \"Dear son,","it's time you took a wife, so get it done!","The autumn's here, and winter's drawing near,","and Sopje has its pretty girls, my dear.\""],"day":"10-09"},{"slug":"ovaj-dom-je-utociste-vase","title_hr":"Ovaj dom je utočište vaše","title_en":"This Home Is Your Refuge","hr":["Sjetite se kad ste mladi bili","i ljubavne snove dok ste snili.","I starost je ljepša kad se druži,","to druženje Dom će da vam pruži."],"en":["Remember when you once were young, and when","you dreamed the dreams of love you dreamed back then.","And old age is more lovely shared with friends,","and friendship is the thing this Home extends."],"day":"10-10"},{"slug":"zov-domovine","title_hr":"Zov domovine","title_en":"The Call of the Homeland","hr":["Rođena ti gruda sreću, ljubav daje,","svako drvo, kamen, dječje radovanje.","To ti tuđa zemlja nikad neće dati.","Maćeha se majkom nikad neće zvati."],"en":["The soil where you were born gives you both love and joy,","each tree, each stone, and all the gladness of a boy;","no foreign land will ever give you this, no other:","a stepmother will never bear the name of mother."],"day":"10-11"},{"slug":"ne-pitam-te","title_hr":"Ne pitam te","title_en":"I Don't Ask You","hr":["Ja se pitam do sad bila gdje si,","da za tebe jučer nisam znao.","Volim tebe takvu kakva jesi,","takvu sam te, mila, upoznao."],"en":["I ask myself where you have been till now,","that until yesterday I never knew you.","I love you as you are, for that is how,","just like that, my dear, I came to know you."],"day":"10-12"},{"slug":"pitas-me","title_hr":"Pitaš me","title_en":"You Ask Me","hr":["Još da mogu da poljubim,","tvoja medna usta mala.","Vjeruj, dušo, da bi tada","moja pjesma sama cvala."],"en":["If, besides, I could but kiss","your small mouth, so honey-sweet,","trust me, darling, then my poem","of itself would bloom, complete."],"day":"10-13"},{"slug":"neposlusni-vrabac","title_hr":"Neposlušni vrabac","title_en":"The Disobedient Sparrow","hr":["U ovoj priči ima","nešto vrjednije od zlata:","nije vam svatko prijatelj","tko vas vadi iz blata."],"en":["In this story there's a lesson","worth more gold than you could spend:","not all those who pull you out","of the mud will be your friend."],"day":"10-14"},{"slug":"zivot-penzionera","title_hr":"Život penzionera","title_en":"A Pensioner's Life","hr":["Penzioner svakog dana","pismonošu željno čeka.","Za nagradu svome radu","što je rint'o pola vijeka.","Cijelo vrijeme mašta, sanja,","što će moći sve da kupi.","\"Kupit ću si drva sada,","dok još zima ne nastupi.\""],"en":["Every day the pensioner","waits for when the postman's due:","his reward for all the slaving","half a century right through.","All the time he dreams and muses","what he'll buy, the things he'll get:","\"Now I'll buy myself some firewood,","while the winter's not here yet.\""],"day":"10-15"},{"slug":"zasto-covjek-nije-kao-dijete","title_hr":"Zašto čovjek nije kao dijete","title_en":"Why Is Man Not Like a Child","hr":["Zašto čovjek nije kao dijete","što koru kruha među sobom dijeli?","Zašto mnogi zemaljsko blago","samo za sebe želi?"],"en":["Why is man not like a child","that will share its crust of bread with all its friends?","Why do many want earth's riches","only for their selfish ends?"],"day":"10-16","occ_hr":"Svjetski dan kruha · napisano na današnji dan, 1975.","occ_en":"World Bread Day · written on this day in 1975"},{"slug":"ne-mogu-te-zaboraviti","title_hr":"Ne mogu te zaboraviti","title_en":"I Cannot Forget You","hr":["Ja nikada ne ću zaboravit moći,","sa tvojega lica kad pročitah sreću.","I nikada s drugom sretan biti ne ću,","kao s tobom svake provedene noći."],"en":["I never, ever shall be able to forget","the happiness that I could read upon your face;","and never with another woman in your place","be happy as with you on all the nights we met."],"day":"10-17"},{"slug":"gljive","title_hr":"Gljive","title_en":"Mushrooms","hr":["Pripazite, djeco,","kad berete gljive,","neke su crvene,","neke opet sive.","Sve koje su lijepe,","mora znati svatko,","one su opasne","i otrovne jako."],"en":["Watch out, children, when","you're mushrooming today:","some of them are red,","and some of them are grey.","All the pretty ones,","as everyone should know,","are dangerous and very","poisonous, oh no!"],"day":"10-18"},{"slug":"sva-godisnja-doba","title_hr":"Sva godišnja doba","title_en":"All the Seasons","hr":["U ljubavi našoj sve do ovih dana.","Sva godišnja doba prošla su kroz mene.","Od najljepše sreće pa do bolnih rana.","Od žarkoga ljeta do zime studene."],"en":["In our love, up to these days, right from the start,","all the seasons of the year through me have rolled:","from the sweetest joy to wounds that ache and smart,","from the burning summer to the winter's cold."],"day":"10-19","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"volim-te-lavicu","title_hr":"Volim te laviću","title_en":"I Love You, Little Lion","hr":["Koliko si puta,","draga, meni rekla:","volim te laviću!","Dok je Drava tekla."],"en":["How often, my darling,","you told me, you'd say:","\"I love you, little lion!\"","while the Drava flowed away."],"day":"10-20","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"sto-je-drvo","title_hr":"Što je drvo","title_en":"What Is a Tree?","hr":["Tada pčele cvijet oplode,","iza cvijeta plod urodi,","a s jeseni, kad sazori –","najljepše je u prirodi."],"en":["Bees then pollinate the blossom,","after blossom, fruit will grow,","and in autumn, when it's ripened,","nature has no finer show."],"day":"10-21","occ_hr":"napisano na današnji dan, 2010. (inačica „Pod krošnjom kestena“)","occ_en":"written on this day in 2010 (the version “Under the Chestnut's Crown”)"},{"slug":"ja-volim-nadu","title_hr":"Ja volim Nadu","title_en":"I Love Nada","hr":["Vjerujete mi, dečki,","nisam više dijete.","Ja volim Nadu","iz klupe pete!"],"en":["Believe me now, fellows,","I'm not a kid, I repeat:","I love Nada","from the fifth seat!"],"day":"10-22"},{"slug":"domovino-moja","title_hr":"Domovino moja","title_en":"My Homeland","hr":["Zemljo moja, srcu najmilija,","ja sam tebi dao zavjet sveti:","Ako treba, život ću ti dati,","tu sam rođen, tu ću i umrijeti!"],"en":["O my land, the dearest to my heart,","I have sworn you a sacred vow, that I,","if need be, will give my life for you:","here I was born, and here I'll also die!"],"day":"10-23"},{"slug":"belisce","title_hr":"Belišće","title_en":"Belišće","hr":["Jednom ljubljah djevojku kraj Drave.","Pa i sada kada se tog sjetim,","preda mnom su njene oči plave.","Oj, Belišće mjesto pokraj Drave!"],"en":["Once I loved a girl by Drava's side;","even now, whenever I recall,","her blue eyes before me open wide.","Oh, Belišće, the town by Drava's side!"],"day":"10-24"},{"slug":"smrt-starog-hrasta","title_hr":"Smrt starog hrasta","title_en":"Death of the Old Oak","hr":["Nema više starog hrasta,","u Valpovu pokraj pruge.","Još jedino čujem vjetar,","kako cvili prepun tuge."],"en":["Now the old oak is no more","in Valpovo by the rails.","All I hear now is the wind:","full of sorrow, how it wails."],"day":"10-25"},{"slug":"podravino-diko-moja","title_hr":"Podravino, diko moja","title_en":"Podravina, My Pride","hr":["Da ozarim Sopju lice","kao pjesnik, ja ću znati.","Svojim srcem, svojim perom,","svu ljepotu ću mu dati."],"en":["How to light up Sopje's face,","as a poet, I will know:","with my heart and with my pen","all its beauty I'll bestow."],"day":"10-26"},{"slug":"ni-postaru-nije-lako","title_hr":"Ni poštaru nije lako","title_en":"It's Not Easy for the Postman Either","hr":["Nekad sunce, nekad kiše,","nekad torbu tegli više.","Ni poštaru nije lako,","to ne može biti svatko!"],"en":["Sometimes sun, and sometimes rain,","sometimes more to drag and strain;","nor is a postman's life so sweet:","not just anyone could walk that beat!"],"day":"10-27","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"dolazak-zime","title_hr":"Dolazak zime","title_en":"The Coming of Winter","hr":["Vjeverica mala hranu skuplja,","u svoju je ostavu sprema.","Na topli jug su otišle laste,","ni roda više nema."],"en":["A little squirrel gathers up her food","and stores it in her pantry there;","the swallows have flown off to the warm south,","and not a stork is anywhere."],"day":"10-28"},{"slug":"bol-kroz-zivot","title_hr":"Bol kroz život","title_en":"A Lifetime of Pain","hr":["Ljudima si puno puta,","u pomoći, Gospo, bila,","iako si i ti gorke,","na svom putu suze lila!"],"en":["Many times you've helped, Our Lady,","people in their pain and fears,","though you too along your journey","shed your own most bitter tears!"],"day":"10-29"},{"slug":"nela","title_hr":"Nela!","title_en":"Nela!","hr":["Kad Ti Muze maštu pruže","i životne cvatu ruže,","nova pjesma kad se javi,","na papir je odmah stavi."],"en":["When the Muses lend you flight","and life's roses bloom so bright,","when a new poem comes to call,","on the paper write it all."],"day":"10-30","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"cvjetni-san","title_hr":"Cvjetni san","title_en":"A Dream of Flowers","hr":["Sve je tako brzo prošlo,","kao vjetrom odnesen dan,","i cvijeće sa tog prozora","za mene je ostao san."],"en":["All of it has passed so quickly,","like a day the wind has swept,","and the flowers at that window","only in my dreams are kept."],"day":"10-31"},{"slug":"pjesnikova-zelja-1983","title_hr":"Pjesnikova želja","title_en":"The Poet's Wish","hr":["Jednom kada odem","u rajska blaženstva","ponekada dođi,","moj grob obiđi."],"en":["Some day, when I've gone","to the bliss of heaven,","now and then, come round,","visit where I lie."],"day":"11-01","occ_hr":"Svi sveti","occ_en":"All Saints' Day","note_hr":"Ivan Benak počiva na valpovačkom groblju.","note_en":"Ivan Benak rests in the Valpovo cemetery.","note_url":"https://www.google.com/maps/search/?api=1&query=45.669460%2C18.401563"},{"slug":"najdrazima-ja-darujem-dusu","title_hr":"Najdražima ja darujem dušu","title_en":"To My Dearest I Give My Soul","hr":["Prošao je život kao jeka","i odnio dio naših snova.","Najdražima, obitelji mojoj,","nek' im radost pruži knjiga ova."],"en":["Like an echo, life has passed and gone,","and has carried part of our dreams away.","To the ones I love most, my family,","may this book bring gladness every day."],"day":"11-02","occ_hr":"Dušni dan","occ_en":"All Souls' Day"},{"slug":"pjesma-valpovu","title_hr":"Pjesma Valpovu","title_en":"A Poem for Valpovo","hr":["Dođe jesen i lišće uvene,","dani kratki, a noć je velika.","Kada mi se sklope oči snene,","Valpovo je opet meni dika."],"en":["Autumn comes, the leaves fade, one and all,","days are short, the nights are long and deep;","when at last my sleepy eyelids fall,","Valpovo remains my pride in sleep."],"day":"11-03","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"sve-dane-moje","title_hr":"Sve dane moje","title_en":"All My Days","hr":["Sve dane moje radosti,","tebi sam, draga, dao.","Najljepšu snagu mladosti,","no, ipak mi nije žao."],"en":["All my days of joy and cheer","I have given all to you,","my youth's finest strength, my dear,","yet it's nothing that I rue."],"day":"11-04"},{"slug":"posljednji-cjelov","title_hr":"Posljednji cjelov","title_en":"The Last Kiss","hr":["Kroz moj bolni život ti si prošetala.","Poljupcima vrelim rane si vidala.","Milujući tebe sreća mi je sjala,","sada sa mog neba zvijezda je nestala."],"en":["Through my life of pain you strolled along your way;","with burning kisses you would heal my wounds each day;","caressing you, my joy shone bright as the sun's ray;","now from my sky a star has vanished clean away."],"day":"11-05"},{"slug":"rasplinuti-snovi","title_hr":"Rasplinuti snovi","title_en":"Dreams Dissolved","hr":["Kad zora svane","i sunce sine,","te snove moje","u maglu raspline."],"en":["When dawn is breaking","and the sun shines bright,","it melts these dreams of mine","to mist in morning light."],"day":"11-06"},{"slug":"postarica","title_hr":"Poštarica","title_en":"The Post-Office Girl","hr":["Što je lijepo poštarica biti,","divna glava za šalterom viri,","iza vjeđa dragulji joj skriti,","sa pogledom moju dušu širi."],"en":["What a lovely thing, to ply the post-girl's trade!","a pretty head peeps from the counter, just inside;","jewels hidden underneath her eyelids' shade,","with a glance she opens up my soul so wide."],"day":"11-07","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"dao-sam-ti-boli","title_hr":"Dao sam ti boli","title_en":"I Gave You Pain","hr":["Kazni me, odbaci, prezri","i to bih sve prebolio,","no, nikada nemoj reći,","da nisam te ludo volio."],"en":["Punish, cast me off, and scorn me:","all of that I could live through;","but you must not ever say","that I did not madly love you."],"day":"11-08"},{"slug":"san-o-sreci","title_hr":"San o sreći","title_en":"A Dream of Happiness","hr":["A ja malen još nejačak,","daleki sam snio sanak.","U mašti sam sretan bio,","a na javi plaćo danak."],"en":["And I, little, weak, each day","dreamed a dream of far away.","In my fancies I was happy,","but awake, I had to pay."],"day":"11-09"},{"slug":"etno-kuca-semialjac-kate","title_hr":"Etno kuća Semialjac Kate","title_en":"Kata Semialjac's Ethno House","hr":["Kuhinja je ista kao prije:","žena muža sa objedom čeka,","prije ručka rakija se pije,","pa večera i postelja meka."],"en":["The kitchen is the same as long ago:","the wife awaits her husband, dinner laid;","before the meal the rakija must flow,","then supper, and a soft bed ready made."],"day":"11-10"},{"slug":"kad-kocije-zasviraju","title_hr":"Kad Kočije zasviraju","title_en":"When Kočije Strike Up","hr":["Kad Martinje kaže svoje,","pravo vino je u čaši.","A „KOČIJE“ tada poje:","„DOBRO VINO TAMBURAŠI“!"],"en":["When St Martin has his say,","real wine's in the glass again;","then Kočije sing away:","“Good Wine, You Tambura Men!”"],"day":"11-11","occ_hr":"Martinje · napisano na današnji dan, 2014.","occ_en":"St Martin's Day · written on this day in 2014"},{"slug":"suzani-za-rodendan","title_hr":"Suzani za rođendan","title_en":"For Suzana's Birthday","hr":["Za tren oka nestalo djetinjstvo,","u nepovrat otišli su snovi.","Kćeri mila, od srca ti želim,","da ti budu sretni dani novi."],"en":["In a blink your childhood disappeared,","and your dreams have gone, not to return.","Dearest daughter, from my heart I wish","that new happy days be yours in turn."],"day":"11-12","occ_hr":"Rođendan kćeri Suzane","occ_en":"His daughter Suzana's birthday"},{"slug":"volio-bih-da-sam-vjetar","title_hr":"Volio bih da sam vjetar","title_en":"I Wish I Were the Wind","hr":["Volio bih da sam vjetar!","Nježni lahor ja bih bio.","Bijelo lice, medna usta,","svojoj dragoj bih ljubio."],"en":["How I wish I were the wind, oh!","I would be a soft breeze blowing;","my love's white face, lips of honey,","I would kiss them, gently flowing."],"day":"11-13"},{"slug":"neposlusni-vrabac","title_hr":"Neposlušni vrabac","title_en":"The Disobedient Sparrow","hr":["Kad netko visoko leti","i uživa lude slasti,","tko je drzak i zločest,","taj može nisko pasti."],"en":["When somebody flies up high,","revelling in wild delight,","if he's cheeky, if he's naughty,","he can tumble from that height."],"day":"11-14"},{"slug":"sokadijo-moj-voljeni-kraju","title_hr":"Šokadijo moj voljeni kraju","title_en":"Šokadija, My Beloved Land","hr":["Volim tebe mili zavičaju,","jer sam rođen u tvojemu kraju.","Da se rodim opet bi tvoj bio","i šokicu dragu oženio."],"en":["I love you so, dear homeland of my birth,","for I was born in you, on your own earth;","were I reborn, I'd still be yours, and then","I'd wed a dear Šokica once again."],"day":"11-15"},{"slug":"od-djetinjstva-do-starackih-dana","title_hr":"Od djetinjstva do staračkih dana","title_en":"From Childhood to Old Age","hr":["Što je lijepo uvijek kratko traje","i mladost je nestala u trenu.","Djeca su mi kuću popunila,","pa mi snaga na posao krenu."],"en":["What is lovely never lasts for long,","and in a moment youth had slipped away;","children came and filled my house, and so","all my strength went off to work each day."],"day":"11-16"},{"slug":"sokacki-obicaji","title_hr":"Šokački običaji","title_en":"Šokac Customs","hr":["Nema više konja da dvorištem njište,","mjesto njih traktori sokacima bruje.","Nema mladih snaša da u kolu vrište,","sve je utihnulo, ništa se ne čuje."],"en":["There are no more horses in farmyards to neigh,","in their place, only tractors go droning down lanes;","no young wives in the kolo now whooping away,","all has fallen silent, and no sound remains."],"day":"11-17"},{"slug":"vojnikova-majka","title_hr":"Vojnikova majka","title_en":"The Soldier's Mother","hr":["Ubiše mi sina,","od osamnaest godina.","Život je izgubio u boju,","braneći domovinu svoju."],"en":["They killed my son,","eighteen years beneath the sun.","He fell in battle, making a stand,","defending his own native land."],"day":"11-18","occ_hr":"Dan sjećanja na Vukovar","occ_en":"Vukovar Remembrance Day"},{"slug":"starac","title_hr":"Starac!","title_en":"The Old Man","hr":["Vrati bože, osmjeh, radost,","svakom stvoru da se divim.","Slatku ljubav, sretnu mladost","još jedanput da proživim."],"en":["Give me back, O God, my smile","and the joy to marvel still;","sweetest love and youth, a while","let me live them, if you will."],"day":"11-19"},{"slug":"zivotna-premija","title_hr":"Životna premija","title_en":"Life's Bonus","hr":["Mili Bože, lijepi dan me čeka,","barem da je ovako dovijeka."],"en":["Dear Lord, a lovely day lies here in store;","if only it were so for evermore!"],"day":"11-20","occ_hr":"napisano na današnji dan, 2007.","occ_en":"written on this day in 2007"},{"slug":"prijatelju-dokonalu","title_hr":"Prijatelju Dokonalu!","title_en":"To My Friend Dokonal!","hr":["Ovo divno prijateljstvo,","što je časno među nama,","ta suradnja obostrana,","neka traje godinama."],"en":["This fine friendship that we share,","held in honour by us two,","and our working hand in hand,","may it last the long years through."],"day":"11-21","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"sretan-imendan-priji-kati","title_hr":"Sretan imendan priji Kati","title_en":"A Happy Name Day to Our Prija Kata","hr":["Mili, Bože, što godine lete,","pa na pleća kao teret slete.","Zima tiho kuca mi na vrata,","eto stiže već i sveta Kata."],"en":["Dear God, how swiftly all the years fly by,","and on our shoulders like a burden lie;","the winter's softly knocking at my door,","and here's Saint Kata, come around once more."],"day":"11-22","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"saljes-li-mi-snove","title_hr":"Šalješ li mi snove","title_en":"Do You Send Me Dreams","hr":["U noći meni divne snove šalješ","i ljubav svoju koju rado primam.","U snovima slatke poljupce mi daješ,","u tihoj noći kada divno snivam."],"en":["At night you send me lovely dreams, and you","send me your love as well, which I am glad to keep;","in dreams you give me your sweet kisses too,","in the still night, while blissfully I sleep."],"day":"11-23","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"treca-dob-u-dnevnom-boravku","title_hr":"Treća dob u „Dnevnom boravku“","title_en":"The Third Age at the \"Day Centre\"","hr":["Svakog dana ovdje dođu,","mnogo dama našeg kraja,","preko dana da si nađu,","zemaljskoga malo raja."],"en":["Every day the ladies come,","many from around our way,","just to find themselves a crumb","of earthly heaven through the day."],"day":"11-24","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"uspavanka","title_hr":"Uspavanka","title_en":"Lullaby","hr":["Čeka te čarobna","ljuljačka snova,","u san te uljulja","uspavanka ova."],"en":["A magical swing","of dreams waits on high,","and you're rocked off to sleep","by this lullaby."],"day":"11-25"},{"slug":"sopje-selo-moga-djetinjstva","title_hr":"Sopje, selo moga djetinjstva","title_en":"Sopje, Village of My Childhood","hr":["Još se sjećam svog djetinjstva,","divna nošnja se nosila,","što je bila ukras selu,","folkloraše okitila."],"en":["I recall my childhood still:","lovely costumes then were worn,","the adornment of the village,","and the dancers they'd adorn."],"day":"11-26","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"dodi-mi-draga","title_hr":"Dođi mi, draga","title_en":"Come to Me, Darling","hr":["U zagrljaj dođi meni,","kad zvjezdane budu noći.","Probudi moj život sneni,","a poljupcem sklopi oči."],"en":["Come and hold me close and tight","when the nights have starry skies;","wake my drowsy life to light,","with a kiss then close my eyes."],"day":"11-27"},{"slug":"bol-kroz-zivot","title_hr":"Bol kroz život","title_en":"A Lifetime of Pain","hr":["Trpio sam mnogo bola,","na svom putu punom jada,","Bog mi bio u pomoći,","od djetinjstva sve do sada."],"en":["I have suffered pain so often","on my road of grief and tears;","God has been my help and comfort","from my childhood, all my years."],"day":"11-28"},{"slug":"kolinje-u-drenovcima","title_hr":"Kolinje u Drenovcima","title_en":"Kolinje in Drenovci","hr":["Drenovčani, plemeniti ljudi,","marljivi su i pitome ćudi,","oni štuju stare običaje,","pa kolinje po tri dana traje."],"en":["The Drenovci folk are noble people, true,","hard-working, and of gentle nature, too;","they honour all the customs of the past,","so for three days their kolinje will last."],"day":"11-29","occ_hr":"Vrijeme kolinja","occ_en":"Kolinje season"},{"slug":"ide-bozic-i-sveti-nikola-i-poklona-nosi-puna-kola","title_hr":"Ide Božić i sveti Nikola i poklona nosi puna kola","title_en":"Here Come Christmas and Saint Nicholas with a Cartful of Gifts","hr":["U božićnoj tihoj noći,","Božićnjak je znao doći.","Dok sam sladak sanak snio,","poklone mi ostavio."],"en":["On the silent Christmas night","Father Christmas would alight.","While I dreamed my sweet dreams, he","left some presents there for me."],"day":"11-30"},{"slug":"molim-paket-djeda-mraze","title_hr":"Molim paket Djeda Mraze!","title_en":"A Parcel, Please, Grandfather Frost!","hr":["Molim paket Djeda Mraze!","Ja sam ti još sasvim mala.","Zato ništa drugo ne znam,","Nego reći: Lijepo hvala!"],"en":["A parcel, please, Grandfather Frost!","I am still so very small.","That is why I know no more","than to say \"Thank you!\", that's all."],"day":"12-01"},{"slug":"prva-zekina-zima","title_hr":"Prva Zekina zima","title_en":"Little Bunny's First Winter","hr":["Poželio zeko mali","majku, da mu krevet grije,","od snijega je polje bijelo,","cijele noći spav'o nije."],"en":["Little bunny longed for Mother","there to warm his bed at night;","not a wink he slept till morning,","and the field was snowy white."],"day":"12-02"},{"slug":"sopje-nekada-i-sada","title_hr":"Sopje nekada i sada","title_en":"Sopje, Then and Now","hr":["Daleko sam od mog sela,","al' me srce k njemu vuče.","Još se sjećam onih dana,","kad sam bio tu kod kuće."],"en":["I am far from my own village,","but my heart pulls me that way;","I remember still the time","when at home I used to stay."],"day":"12-03"},{"slug":"ovaj-dom-je-utociste-vase","title_hr":"Ovaj dom je utočište vaše","title_en":"This Home Is Your Refuge","hr":["Kad vas jutro iz toplog sna budi","i kad danak na ljepotu sluti,","a prijatelj kraj tebe nasmije,","eto, to su životne premije."],"en":["When morning wakes you from your cosy bed","and the young day foretells fine things ahead,","and when a friend beside you smiles at you,","why, these are life's own bonuses come due."],"day":"12-04","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"cekao-sam-tebe","title_hr":"Čekao sam tebe!","title_en":"I Waited for You!","hr":["Tražio sam, draga, tvoje mile oči,","što me toplo griju u studenoj noći.","I medene usne, tvoga slatkog smijeha,","poljubaca pune i čedne bez grijeha."],"en":["I sought, my darling, for your dear eyes' gentle light,","that warms me through so tenderly in the cold night,","and honey lips, where your sweet laughter would begin,","so full of kisses, chaste and pure and free of sin."],"day":"12-05"},{"slug":"djecji-snovi","title_hr":"Dječji snovi","title_en":"Children's Dreams","hr":["Zapamtite, tko je mio","taj po noći divno sanja,","ali tko je zločest bio,","toga ljuta šiba ganja."],"en":["So remember: each good child","has sweet dreams the whole night through;","but the naughty and the wild,","feel the stinging switch pursue."],"day":"12-06","occ_hr":"Sveti Nikola","occ_en":"St Nicholas' Day"},{"slug":"osvrt-na-ljubav","title_hr":"Osvrt na ljubav","title_en":"A Look at Love","hr":["Sretan mačor u krevetu prede,","sve što treba u krilašcu nađe,","tu su snovi koji zlata vrijede,","ništa nema od ljubavi slađe."],"en":["In bed a happy tomcat purrs, all curled,","in a little lap he finds all he needs, complete;","here are dreams worth all the gold in the world,","nothing can compare with love so sweet."],"day":"12-07","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"ne-budi-me-majko-rano","title_hr":"Ne budi me, majko, rano","title_en":"Don't Wake Me Early, Mother","hr":["Ne budi me, majko, rano.","Ne kidaj mi divne snove,","kada zoveš moje ime,","mislim da me draga zove."],"en":["Mother, do not wake me early,","leave my lovely dreams unbroken:","when you call my name, I fancy","it's my darling who has spoken."],"day":"12-08"},{"slug":"tri-majstora","title_hr":"Tri majstora","title_en":"Three Craftsmen","hr":["„Ja sam važan!“ veli krojač,","„kod mene se ruho šije.","Pravim kaput, prsluk, hlače,","da ljudima zima nije.“"],"en":["\"I'm important!\" says the tailor,","\"here is where the clothes are sewn:","coats I make, and vests, and trousers,","so the cold leaves folk alone.\""],"day":"12-09"},{"slug":"tuzno-je-biti-sam","title_hr":"Tužno je biti sam","title_en":"It's Sad to Be Alone","hr":["Zato si nađi,","životnog druga,","nikad ne budi sam.","Život je slađi,","manja je tuga,","vjeruj mi,","ja to znam."],"en":["Go, then, seek and find","a companion true;","never be alone.","Life's more sweet, more kind,","and less sorrow, too;","trust me,","this I've known."],"day":"12-10","occ_hr":"napisano na današnji dan, 1989.","occ_en":"written on this day in 1989"},{"slug":"kitisanci","title_hr":"Kitišanci","title_en":"Kitišanci","hr":["Kitišanci selo malo,","na kartama ne postoji,","tek stotinjak kuća ima,","al' godina puno broji."],"en":["Kitišanci, little village,","on no map will it appear;","just a hundred houses has it,","but it counts full many a year."],"day":"12-11","occ_hr":"napisano na današnji dan, 1993.","occ_en":"written on this day in 1993"},{"slug":"puna-casa-ljubavi","title_hr":"Puna čaša ljubavi","title_en":"A Glass Brimming with Love","hr":["U mom srcu i u duši,","ljubavi je puna čaša,","ako me još, draga, voliš","vrati mi se ovog časa."],"en":["In my heart and in my soul","love has filled a glass for two;","if you love me still, my darling,","come back now, this hour, please do!"],"day":"12-12","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"sveta-lucija","title_hr":"Sveta Lucija","title_en":"Saint Lucy","hr":["Svima vama što ste u toj tami","usamljeni u životu sami,","nek' vam teku u ljepoti dani,","od LUCIJE SVETE OBASJANI."],"en":["All of you who in that darkness stay,","lonely and alone along life's way,","may your days flow on in beauty bright,","RADIANT WITH HOLY LUCY'S LIGHT."],"day":"12-13","occ_hr":"Sveta Lucija","occ_en":"St Lucy's Day"},{"slug":"moj-voljeni-grade","title_hr":"Moj voljeni grade","title_en":"My Beloved Town","hr":["Oj, Valpovo, moj voljeni grade,","ti mi rasteš kao vita jela,","na njedrima divne Slavonije,","ljepota me tvoja zanijela."],"en":["O Valpovo, my own beloved town,","like a slender fir you're growing tall","on the breast of fair Slavonia;","and your beauty holds me in its thrall."],"day":"12-14"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["Kad sam bio u trbuhu majke,","nikada mi nije bilo bolje.","Mene ništa ni pitali nisu,","rodiše me protiv moje volje."],"en":["When I was lying in my mother's womb,","I never had it better there. Until,","without so much as asking what I wished,","they bore me into life against my will."],"day":"12-15","occ_hr":"napisano na današnji dan, 1990.","occ_en":"written on this day in 1990"},{"slug":"diljem-slavonije","title_hr":"Diljem Slavonije","title_en":"All Across Slavonia","hr":["U Kutjevu zaustavim vrijeme,","pijuć' vino nekoliko dana,","uz tambure i Šokice mlade,","volim život i to mi je mana."],"en":["In Kutjevo I make the time stand still,","drinking wine as several days go by,","with the tamburas and young Šokice;","I love life, a fault I can't deny."],"day":"12-16","occ_hr":"napisano na današnji dan, 1993.","occ_en":"written on this day in 1993"},{"slug":"dragice","title_hr":"Dragice!","title_en":"Dragica!","hr":["Kao rijeka bez povratka,","isto tako život teče.","Blago onom ljudskom stvoru,","tko zdravstvene ima sreće."],"en":["Like a river never turning","back, so too our life flows on;","blessed is the human creature","who has health to count upon."],"day":"12-17","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"cestitka-unucima","title_hr":"Čestitka unucima","title_en":"New Year's Greetings to Our Grandchildren","hr":["Dobro zdravlje pored svega,","to je naša želja jaka!","Sve najbolje vama žele","vaši dobri djed i baka!"],"en":["And good health, above all things:","that's the wish we firmly hold!","All the best to you are sending","Grandpa, Grandma, good as gold!"],"day":"12-18","occ_hr":"napisano na današnji dan, 1988.","occ_en":"written on this day in 1988"},{"slug":"djeda-mraz","title_hr":"Djeda Mraz","title_en":"Grandfather Frost","hr":["Djeda Mraze, dragi, mio,","darove si nam donio.","Gdje si tako dugo bio?","Jesi li se umorio?"],"en":["Dear, sweet Grandpa Frost, we're saying:","presents here for us you're laying!","Where so long have you been staying?","Are you tired out from sleighing?"],"day":"12-19"},{"slug":"zanos","title_hr":"Zanos","title_en":"Rapture","hr":["Oh, ljubavi moja!","Slatka si i mila,","kao majka čedu,","kad raširi krila."],"en":["Oh, my love, my darling!","You're so sweet and mild,","like a mother spreading","her wings above her child."],"day":"12-20","occ_hr":"napisano na današnji dan, 1973.","occ_en":"written on this day in 1973"},{"slug":"sretan-bozic","title_hr":"Sretan Božić","title_en":"Merry Christmas","hr":["Sretan Božić vama","Ja iskreno želim.","Poklonima vašim","I ja se veselim."],"en":["Merry Christmas, one and all,","is my wish, sincere and true;","at the presents that you get","I'll be glad as well as you."],"day":"12-21","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"draga-generacijo-2013","title_hr":"Draga generacijo!","title_en":"My Dear Generation!","hr":["Među ljudstvom neka sloga vlada","Ne bilo vam staračkoga jada","Da se lakše u životu diše","I ratova da ne bude više."],"en":["May among all folk accord hold sway,","may the woes of old age stay away,","so that breathing's easier in life,","and no more of wars and all their strife."],"day":"12-22","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"dragi-denis","title_hr":"Dragi Denis","title_en":"Dear Denis","hr":["Neka ti Božić","i godina Nova","radosti pruže","i dobro veselje,","puno zdravlja,","ostvarenje snova.","To su tvoje bake","i djeda želje."],"en":["May Christmas bring you,","and the New Year, too,","gladness and plenty","of joy and good cheer,","lots of good health,","and your dreams come true.","So wish your Grandma","and your Grandpa, dear."],"day":"12-23","occ_hr":"napisano na današnji dan, 2005.","occ_en":"written on this day in 2005"},{"slug":"ide-bozic-i-sveti-nikola-i-poklona-nosi-puna-kola","title_hr":"Ide Božić i sveti Nikola i poklona nosi puna kola","title_en":"Here Come Christmas and Saint Nicholas with a Cartful of Gifts","hr":["Na Badnjak smo sretni bili","i božićni bor kitili.","Stavljali smo sve ukrase,","još jabuke i orase."],"en":["Christmas Eve, how glad were we,","trimming up the Christmas tree!","We hung baubles here and there,","apples, walnuts, everywhere."],"day":"12-24","occ_hr":"Badnjak","occ_en":"Christmas Eve"},{"slug":"gospodi-ani-gillinger-iz-ivankova","title_hr":"Gospođi Ani Gillinger iz Ivankova","title_en":"To Mrs Ana Gillinger of Ivankovo","hr":["Nek' Vam bude SRETAN BOŽIĆ","I GODINA ova NOVA,","a najviše dobrog zdravlja:","želi Ivo iz Valpova!"],"en":["May you have a MERRY CHRISTMAS","and a NEW YEAR's happy glow;","and good health, above all things,","wishes Ivo from Valpovo!"],"day":"12-25","occ_hr":"Božić","occ_en":"Christmas Day"},{"slug":"ja-volim","title_hr":"Ja volim","title_en":"What I Love","hr":["Ja volim tihe,","zvjezdane noći.","I topli kutak","ljubavnog žara.","Skromni, mali,","tihi, mili dom."],"en":["I love the quiet,","starry nights,","and a warm corner","where love's embers glow.","Small and modest,","a quiet, homely nest."],"day":"12-26","occ_hr":"Sveti Stjepan","occ_en":"St Stephen's Day"},{"slug":"noge-bose-a-cipele-cure","title_hr":"Noge bose a cipele cure","title_en":"Bare Feet and Leaky Shoes","hr":["Pukla mi je cipela na peti,","pa mi stalno rupa na pameti.","Rupu gledam, mislim sad je zgoda,","pa popravim dok ne uđe voda."],"en":["My shoe's burst open at the heel behind,","and so I've got a hole upon my mind.","I eye the hole and think: now is the day","to fix it, before water finds its way."],"day":"12-27","occ_hr":"napisano na današnji dan, 1996.","occ_en":"written on this day in 1996"},{"slug":"sretna-vam-nova-godina-draga-generacijo","title_hr":"Sretna vam Nova godina, draga generacijo","title_en":"A Happy New Year to You, Dear Generation","hr":["Uskoro nam stiže Novo Ljeto,","što nam nosi neka bude sretno,","puno sreće i zdravlja i para,","sve probleme nek' odnese stara."],"en":["The New Year's soon upon us: may it be","that what it brings brings joy to you and me,","with lots of luck and health and cash to hold;","may all our troubles go off with the old."],"day":"12-28"},{"slug":"hej-zivote","title_hr":"Hej živote","title_en":"Hey There, Life","hr":["Hej živote, malo stani!","Sretna zoro, daj osvani!","Radosnice, suzo, kani!","Da nam budu ljepši dani.","Dobro zdravlje, sreće puno,","povrh svega, zlatno runo!"],"en":["Hey there, life, don't rush, go slow!","Happy dawn, rise up and glow!","Tears of joy, come, overflow,","so our days more lovely grow!","Health and happiness in store,","and the Golden Fleece, what's more!"],"day":"12-29"},{"slug":"cestitka-unucima","title_hr":"Čestitka unucima","title_en":"New Year's Greetings to Our Grandchildren","hr":["Godinicu sretnu Novu,","čestitamo vama svima!","I darova puna kola,","našim dragim unucima!"],"en":["Happy little New Year's greetings","we send out to all of you!","And a cartload full of presents","for our dear grandchildren too!"],"day":"12-30"},{"slug":"novogodisnje-zelje","title_hr":"Novogodišnje želje","title_en":"New Year's Wishes","hr":["Novo ljeto kad ura najavi,","da sam s tobom i da se veselim,","kad se radost na tom svijetu slavi,","da ti prvi čestitke poželim."],"en":["When the clock rings in the year that's new,","may I be at your side, rejoicing here;","when joy is celebrated the whole world through,","may I be first to wish you a happy year."],"day":"12-31","occ_hr":"Stara godina","occ_en":"New Year's Eve"}];
